func pcFWidth(f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, slot int32, code int32) int32 {
	if slot == 0 {
		return pdffont.PfnWidth(f0, code)
	}
	if slot == 1 {
		return pdffont.PfnWidth(f1, code)
	}
	if slot == 2 {
		return pdffont.PfnWidth(f2, code)
	}
	return pdffont.PfnWidth(f3, code)
}

func pcFR(f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, slot int32, which int32) int32 {
	// A font's descriptor facts for the `fonts` row: which 0 subtype, 1 /Flags, 2 has a ToUnicode,
	// 3 base encoding, 4 kind (1 simple).
	if slot == 0 {
		if which == 0 {
			return pdffont.PfnSubtype(f0)
		}
		if which == 1 {
			return pdffont.PfnFlags(f0)
		}
		if which == 2 {
			return pdffont.PfnHasTounicode(f0)
		}
		if which == 3 {
			return pdffont.PfnEncoding(f0)
		}
		return pdffont.PfnKindOf(f0)
	}
	if slot == 1 {
		if which == 0 {
			return pdffont.PfnSubtype(f1)
		}
		if which == 1 {
			return pdffont.PfnFlags(f1)
		}
		if which == 2 {
			return pdffont.PfnHasTounicode(f1)
		}
		if which == 3 {
			return pdffont.PfnEncoding(f1)
		}
		return pdffont.PfnKindOf(f1)
	}
	if slot == 2 {
		if which == 0 {
			return pdffont.PfnSubtype(f2)
		}
		if which == 1 {
			return pdffont.PfnFlags(f2)
		}
		if which == 2 {
			return pdffont.PfnHasTounicode(f2)
		}
		if which == 3 {
			return pdffont.PfnEncoding(f2)
		}
		return pdffont.PfnKindOf(f2)
	}
	if which == 0 {
		return pdffont.PfnSubtype(f3)
	}
	if which == 1 {
		return pdffont.PfnFlags(f3)
	}
	if which == 2 {
		return pdffont.PfnHasTounicode(f3)
	}
	if which == 3 {
		return pdffont.PfnEncoding(f3)
	}
	return pdffont.PfnKindOf(f3)
}

func pcNameFind(ar *port.Cells, nh int32, n int32, c0 int32, c1 int32, c2 int32, c3 int32, c4 int32, c5 int32, c6 int32) int32 {
	// 1 when the name nh contains the n (1..7) characters c0.. in a row.
	var ln int32 = pdflex.PlNameLen(ar, nh)
	var i int32 = 0
	var ok int32 = 1
	for (i + n) <= ln {
		ok = 1
		if pdflex.PlNameByte(ar, nh, i) != c0 {
			ok = 0
		}
		if (n > 1) && (pdflex.PlNameByte(ar, nh, i+1) != c1) {
			ok = 0
		}
		if (n > 2) && (pdflex.PlNameByte(ar, nh, i+2) != c2) {
			ok = 0
		}
		if (n > 3) && (pdflex.PlNameByte(ar, nh, i+3) != c3) {
			ok = 0
		}
		if (n > 4) && (pdflex.PlNameByte(ar, nh, i+4) != c4) {
			ok = 0
		}
		if (n > 5) && (pdflex.PlNameByte(ar, nh, i+5) != c5) {
			ok = 0
		}
		if (n > 6) && (pdflex.PlNameByte(ar, nh, i+6) != c6) {
			ok = 0
		}
		if ok == 1 {
			return 1
		}
		i += 1
	}
	return 0
}

func pcFontRow(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, fnt *port.Cells, et *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, slot int32, status int32, key int32) int32 {
	// The `fonts` row of a font the document shows for the first time (its row is its id): object
	// number, subtype, /Flags, whether it has a ToUnicode, base encoding, /BaseFont, ascent, descent,
	// the width of a space (simple fonts), and a style from the flags and the name. P1.6 reads no
	// font programs, /ItalicAngle or /StemV (`pdfnames` has no such names): program 0, italic angle 0,
	// stem -1. A font that would not load has subtype 0 and no metrics.
	var row int32 = evidence.FoNew(fnt, port.CellsAt(cx, cCur+gFobj), 0)
	var nh int32 = pdfdoc.PdDget(src, ar, dc, a, b, st, key, pdfnames.PnBaseFont())
	var flags int32 = 0
	var sty int32 = 0
	var i int32 = 0
	var start int32 = 0
	var ln int32 = 0
	if status == 0 {
		evidence.FoSet(fnt, row, evidence.FnfSubtype(), pcFR(f0, f1, f2, f3, slot, 0))
		flags = pcFR(f0, f1, f2, f3, slot, 1)
		evidence.FoSet(fnt, row, evidence.FnfFlags(), flags)
		evidence.FoSet(fnt, row, evidence.FnfTounicode(), pcFR(f0, f1, f2, f3, slot, 2))
		evidence.FoSet(fnt, row, evidence.FnfEnc(), pcFR(f0, f1, f2, f3, slot, 3))
		evidence.FoSet(fnt, row, evidence.FnfAsc(), pcFQ(f0, f1, f2, f3, slot, 0))
		evidence.FoSet(fnt, row, evidence.FnfDesc(), pcFQ(f0, f1, f2, f3, slot, 1))
		if pcFR(f0, f1, f2, f3, slot, 4) == 1 {
			evidence.FoSet(fnt, row, evidence.FnfSpace(), pcFWidth(f0, f1, f2, f3, slot, 32))
		}
	}
	if (nh != 0) && (pdflex.PlKindOf(ar, nh) == 4) {
		ln = pdflex.PlNameLen(ar, nh)
		start = port.CellsLen(et)
		for i < ln {
			evidence.EtxAppendCp(et, pdflex.PlNameByte(ar, nh, i))
			i += 1
		}
		evidence.FoSet(fnt, row, evidence.FnfTstart(), start)
		evidence.FoSet(fnt, row, evidence.FnfTlen(), ln)
		if pcNameFind(ar, nh, 4, 66, 111, 108, 100, 0, 0, 0) == 1 {
			sty |= model.SyBold()
		}
		if pcNameFind(ar, nh, 6, 73, 116, 97, 108, 105, 99, 0) == 1 {
			sty |= model.SyItalic()
		}
		if pcNameFind(ar, nh, 7, 79, 98, 108, 105, 113, 117, 101) == 1 {
			sty |= model.SyItalic()
		}
	}
	if (flags & 1) != 0 {
		sty |= model.SyMono()
	}
	if (flags & 64) != 0 {
		sty |= model.SyItalic()
	}
	if (flags & 131072) != 0 {
		sty |= model.SySmallcaps()
	}
	if (flags & 262144) != 0 {
		sty |= model.SyBold()
	}
	evidence.FoSet(fnt, row, evidence.FnfStyle(), sty)
	return row
}

func pcFontId(cx *port.Cells, key int32) int32 {
	// The evidence id of a font dictionary: its index in the order the
	// document first showed it. THE BUDGET `fonts-per-doc` (kind 14, at most MAX_FIDS = 512): the font past it has no id, -1, which is the
	// evidence's 'no font' (its glyphs carry -1 and it has no `fonts` row); the text is still read in the font's own encoding, and the page
	// that shows it is flagged (W_FONTS). The same on every host, since the decision is made here.
	var n int32 = port.CellsAt(cx, cNfont)
	var i int32 = 0
	for i < n {
		if port.CellsAt(cx, cFids+i) == key {
			return i
		}
		i += 1
	}
	if n >= port.CellsAt(cx, cFidlim) {
		return -1
	}
	port.CellsSet(cx, cFids+n, key)
	port.CellsSet(cx, cNfont, n+1)
	return n
}

func pcEnsureFont(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, fnt *port.Cells, et *port.Cells) int32 {
	// Make the current font (the graphics state's) resident in a slot and set
	// C_SLOT to it, -1 when there is none. A font is loaded once and kept; the
	// slot that has gone unused longest is the one replaced.
	var key int32 = port.CellsAt(cx, cCur+gFont)
	var i int32 = 0
	var at int32 = 0
	var pick int32 = 0
	var best int32 = 2147483647
	var status int32 = 0
	var fid int32 = 0
	var nbefore int32 = port.CellsAt(cx, cNfont)
	var clock int32 = port.CellsAt(cx, cClock)
	if key == 0 {
		port.CellsSet(cx, cSlot, -1)
		return 0
	}
	clock += 1
	port.CellsSet(cx, cClock, clock)
	for i < 4 {
		at = cSlots + (i * slotStride)
		if port.CellsAt(cx, at+sKey) == key {
			port.CellsSet(cx, at+sUse, clock)
			port.CellsSet(cx, cSlot, i)
			return 0
		}
		if port.CellsAt(cx, at+sUse) < best {
			best = port.CellsAt(cx, at+sUse)
			pick = i
		}
		i += 1
	}
	at = cSlots + (pick * slotStride)
	status = pcFLoad(src, ar, dc, a, b, st, out, f0, f1, f2, f3, pick, key)
	if pdfsrc.PsMissed(src) {
		port.CellsSet(cx, cAbort, 1)
		port.CellsSet(cx, at+sKey, 0)
		port.CellsSet(cx, cSlot, -1)
		return 0
	}
	port.CellsSet(cx, at+sKey, key)
	port.CellsSet(cx, at+sUse, clock)
	port.CellsSet(cx, at+sStatus, status)
	fid = pcFontId(cx, key)
	port.CellsSet(cx, at+sId, fid)
	// A font the document has not shown before gets its `fonts` row, which is its id.
	if (fid >= 0) && (fid == nbefore) {
		pcFontRow(src, ar, dc, a, b, st, cx, fnt, et, f0, f1, f2, f3, pick, status, key)
	}
	if status == 0 {
		port.CellsSet(cx, at+sAsc, pcFQ(f0, f1, f2, f3, pick, 0))
		port.CellsSet(cx, at+sDesc, pcFQ(f0, f1, f2, f3, pick, 1))
		port.CellsSet(cx, at+sVert, pcFQ(f0, f1, f2, f3, pick, 2))
		port.CellsSet(cx, at+sDw2v, pcFQ(f0, f1, f2, f3, pick, 3))
		port.CellsSet(cx, at+sDw2w, pcFQ(f0, f1, f2, f3, pick, 4))
	} else {
		port.CellsSet(cx, at+sAsc, 0)
		port.CellsSet(cx, at+sDesc, 0)
		port.CellsSet(cx, at+sVert, 0)
	}
	port.CellsSet(cx, cSlot, pick)
	if pdfsrc.PsMissed(src) {
		port.CellsSet(cx, cAbort, 1)
	}
	return 0
}

func pcTf(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, n int32) int32 {
	// Tf: the font named by operand 0 from the current Resources, at the size of
	// operand 1. The dictionary is resolved here and loaded at the first glyph.
	var size int64 = pcNum(ox, n, 1)
	var fh int32 = 0
	var raw int32 = 0
	fx.FxPut(cx, cCur+gFs, size)
	if (n >= 1) && (pcKind(ox, 0) == kName) {
		raw = pcResEntry(src, ar, dc, a, b, st, cx, ox, pdfnames.PnFont(), 0)
		if raw != 0 {
			fh = pdfdoc.PdResolve(src, ar, dc, a, b, st, raw)
		}
	}
	if pdfsrc.PsMissed(src) {
		port.CellsSet(cx, cAbort, 1)
		return 0
	}
	if fh == 0 {
		pcWarnSet(cx, wFont)
	} else if pdflex.PlKindOf(ar, fh) != 7 {
		fh = 0
		pcWarnSet(cx, wFont)
	}
	port.CellsSet(cx, cCur+gFont, fh)
	port.CellsSet(cx, cCur+gFobj, 0)
	if (fh != 0) && (raw != 0) {
		if pdflex.PlKindOf(ar, raw) == 9 {
			port.CellsSet(cx, cCur+gFobj, pdflex.PlIntValue(ar, raw))
		}
	}
	return 0
}

func pcMin4(p int64, q int64, r int64, s int64) int64 {
	var m int64 = p
	if q < m {
		m = q
	}
	if r < m {
		m = r
	}
	if s < m {
		m = s
	}
	return m
}

func pcMax4(p int64, q int64, r int64, s int64) int64 {
	var m int64 = p
	if q > m {
		m = q
	}
	if r > m {
		m = r
	}
	if s > m {
		m = s
	}
	return m
}

func pcDirAngle(a int64, b int64) int32 {
	// The angle of the direction (a, b) in page space (y down), by `ev-angle`: halve both until the
	// larger fits 30 bits, so the angle of a matrix axis in 24-bit fixed point keeps all its precision.
	var x int64 = a
	var y int64 = b
	var m int64 = int64(0)
	if x < int64(0) {
		m = int64(0) - x
	} else {
		m = x
	}
	if y < int64(0) {
		if (int64(0) - y) > m {
			m = int64(0) - y
		}
	} else if y > m {
		m = y
	}
	for m > int64(1073741824) {
		x = x / int64(2)
		y = y / int64(2)
		m = m / int64(2)
	}
	return evidence.EvAngle(int32(x), int32(y))
}

func PcPua(cp int32) int32 {
	// D580: the private-use code points of Adobe's Symbol font (U+F8E5..U+F8FE), which TeX's glyph-to-Unicode lists give the
	// big brackets, braces and parentheses and the extension pieces of a tall delimiter (CMEX10), are the characters Unicode
	// later gave them (U+239B..U+23AF, U+23D0, the serif signs). Every other code point is itself.
	if (cp < 63717) || (cp > 63742) {
		return cp
	}
	if cp == 63717 {
		return 9135
	}
	if cp == 63718 {
		return 9168
	}
	if cp == 63719 {
		return 9135
	}
	if cp == 63720 {
		return 174
	}
	if cp == 63721 {
		return 169
	}
	if cp == 63722 {
		return 8482
	}
	if cp <= 63725 {
		return 9115 + (cp - 63723)
	}
	if cp <= 63728 {
		return 9121 + (cp - 63726)
	}
	if cp <= 63731 {
		return 9127 + (cp - 63729)
	}
	if cp == 63732 {
		return 9130
	}
	if cp == 63733 {
		return 9134
	}
	if cp <= 63736 {
		return 9118 + (cp - 63734)
	}
	if cp <= 63739 {
		return 9124 + (cp - 63737)
	}
	return 9131 + (cp - 63740)
}

func pcGlyph(cx *port.Cells, gl *port.Cells, et *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, code int32, ncode int32) int32 {
	// One shown glyph: look the code up, put its cell in page space, record it,
	// advance the text position by its width, the character and word spacing.
	// Recorded (SPEC 8.4.3): the box of its cell; its baseline segment from its origin to its origin plus
	// its advance without Tc and Tw (text space +x, so the spacing stays measurable); `asc` and `desc`
	// (signed distances from the baseline along the up vector, from the font's ascent and descent); `rot`
	// by `ev-angle` from the exact direction of the text matrix's x axis; its fill colour and alpha; the
	// colour-space class when the colour operators said (gray, rgb, cmyk); `z`, the page's paint counter;
	// `mark` (the innermost open mark) and `ocg` (the innermost optional-content mark).
	var slot int32 = port.CellsAt(cx, cSlot)
	var fs int64 = fx.FxGet(cx, cCur+gFs)
	var th int64 = fx.FxGet(cx, cCur+gTh)
	var tc int64 = fx.FxGet(cx, cCur+gTc)
	var tw int64 = fx.FxGet(cx, cCur+gTw)
	var rise int64 = fx.FxGet(cx, cCur+gRise)
	var sat int32 = 0
	var cnt int32 = 0
	var cp0 int32 = -1
	var how int32 = 5
	var w int32 = -1
	var asc int32 = 0
	var desc int32 = 0
	var vert int32 = 0
	var dwv int32 = -100000
	var fid int32 = -1
	var tstart int32 = -1
	var i int32 = 0
	var vch int32 = 0
	var idx int32 = 0
	if slot >= 0 {
		sat = cSlots + (slot * slotStride)
		fid = port.CellsAt(cx, sat+sId)
		if fid < 0 {
			pcWarnSet(cx, wFonts)
		}
		if port.CellsAt(cx, sat+sStatus) == 0 {
			cnt = pcFMap(f0, f1, f2, f3, slot, code)
			how = pcFHow(f0, f1, f2, f3, slot)
			w = pcFWidth(f0, f1, f2, f3, slot, code)
			asc = port.CellsAt(cx, sat+sAsc)
			desc = port.CellsAt(cx, sat+sDesc)
			vert = port.CellsAt(cx, sat+sVert)
			dwv = port.CellsAt(cx, sat+sDw2w)
		}
	}
	if cnt > 0 {
		cp0 = PcPua(pcFCp(f0, f1, f2, f3, slot, 0))
	}
	// A composite font's ToUnicode may say U+0000 or U+FFFD for a glyph it has no value
	// for (Skia does, for the parts of a Devanagari conjunct): that is no value.
	if (cnt == 1) && ((cp0 == 0) || (cp0 == 65533)) {
		cnt = 0
		cp0 = -1
		how = 5
	}
	if w < 0 {
		w = 50000
		pcWarnSet(cx, wWidth)
	}
	if (asc == 0) && (desc == 0) {
		asc = 800
		desc = -200
	}
	var wfx int64 = fx.FxMuldiv(int64(w), fs, int64(100000))
	var x0t int64 = int64(0)
	var x1t int64 = int64(0)
	var y0t int64 = int64(0)
	var y1t int64 = int64(0)
	if vert == 0 {
		x1t = fx.FxMul(wfx, th)
		y0t = fx.FxMuldiv(int64(desc), fs, int64(1000)) + rise
		y1t = fx.FxMuldiv(int64(asc), fs, int64(1000)) + rise
	} else {
		x0t = int64(0) - (wfx / int64(2))
		x1t = wfx / int64(2)
		y0t = fx.FxMuldiv(int64(dwv), fs, int64(100000)) + rise
		y1t = rise
	}
	var p0x int64 = fx.MxX(cx, cM, x0t, y0t)
	var p0y int64 = fx.MxY(cx, cM, x0t, y0t)
	var p1x int64 = fx.MxX(cx, cM, x1t, y0t)
	var p1y int64 = fx.MxY(cx, cM, x1t, y0t)
	var p2x int64 = fx.MxX(cx, cM, x0t, y1t)
	var p2y int64 = fx.MxY(cx, cM, x0t, y1t)
	var p3x int64 = fx.MxX(cx, cM, x1t, y1t)
	var p3y int64 = fx.MxY(cx, cM, x1t, y1t)
	var ma int64 = fx.FxGet(cx, cM)
	var mb int64 = fx.FxGet(cx, cM+2)
	var mc int64 = fx.FxGet(cx, cM+4)
	var md int64 = fx.FxGet(cx, cM+6)
	var hyp int64 = fx.FxHypot(mc, md)
	var size int32 = fx.FxRound(fx.FxMul(hyp, fx.FxAbs(fs)))
	var rot int32 = pcDirAngle(ma, mb)
	var bx0 int32 = fx.FxRound(fx.MxX(cx, cM, int64(0), rise))
	var by0 int32 = fx.FxRound(fx.MxY(cx, cM, int64(0), rise))
	var bx1 int32 = fx.FxRound(fx.MxX(cx, cM, fx.FxMul(wfx, th), rise))
	var by1 int32 = fx.FxRound(fx.MxY(cx, cM, fx.FxMul(wfx, th), rise))
	var up int32 = fx.FxRound(fx.FxMul(y1t-rise, hyp))
	var down int32 = fx.FxRound(fx.FxMul(y0t-rise, hyp))
	var fam int32 = port.CellsAt(cx, cCur+gFam)
	var z int32 = port.CellsAt(cx, cZ)
	var g int32 = evidence.GlNew(gl, port.CellsAt(cx, cPage), fx.FxRound(pcMin4(p0x, p1x, p2x, p3x)), fx.FxRound(pcMin4(p0y, p1y, p2y, p3y)), fx.FxRound(pcMax4(p0x, p1x, p2x, p3x)), fx.FxRound(pcMax4(p0y, p1y, p2y, p3y)), cp0, -1, 0, -1)
	evidence.GlSet(gl, g, evidence.GfHow(), how)
	evidence.GlSet(gl, g, evidence.GfFont(), fid)
	evidence.GlSet(gl, g, evidence.GfSize(), size)
	evidence.GlSet(gl, g, evidence.GfBx0(), bx0)
	evidence.GlSet(gl, g, evidence.GfBy0(), by0)
	evidence.GlSet(gl, g, evidence.GfBx1(), bx1)
	evidence.GlSet(gl, g, evidence.GfBy1(), by1)
	if up >= down {
		evidence.GlSet(gl, g, evidence.GfAsc(), up)
		evidence.GlSet(gl, g, evidence.GfDesc(), down)
	} else {
		evidence.GlSet(gl, g, evidence.GfAsc(), down)
		evidence.GlSet(gl, g, evidence.GfDesc(), up)
	}
	evidence.GlSet(gl, g, evidence.GfRot(), rot)
	evidence.GlSet(gl, g, evidence.GfFill(), port.CellsAt(cx, cCur+gColor))
	evidence.GlSet(gl, g, evidence.GfFalpha(), port.CellsAt(cx, cCur+gAlpha))
	evidence.GlSet(gl, g, evidence.GfStroke(), port.CellsAt(cx, cCur+gScolor))
	evidence.GlSet(gl, g, evidence.GfSalpha(), port.CellsAt(cx, cCur+gSalpha))
	evidence.GlSet(gl, g, evidence.GfClip(), port.CellsAt(cx, cCur+gClip))
	evidence.GlSet(gl, g, evidence.GfMode(), port.CellsAt(cx, cCur+gMode))
	if (fam > 0) && (port.CellsAt(cx, cCur+gMode) != 1) && (port.CellsAt(cx, cCur+gMode) != 5) {
		evidence.GlSet(gl, g, evidence.GfCs(), fam)
	}
	if (port.CellsAt(cx, cCur+gSfam) > 0) && ((port.CellsAt(cx, cCur+gMode) == 1) || (port.CellsAt(cx, cCur+gMode) == 5)) {
		evidence.GlSet(gl, g, evidence.GfCs(), port.CellsAt(cx, cCur+gSfam))
	}
	if port.CellsAt(cx, cCur+gBm) != 0 {
		vch = evidence.VcBlend()
	}
	if port.CellsAt(cx, cCur+gSmask) != 0 {
		vch += evidence.VcSoftmask()
	}
	evidence.GlSet(gl, g, evidence.GfVchk(), vch)
	if port.CellsAt(cx, cCur+gMode) >= 4 {
		if port.CellsAt(cx, cTcn) == 0 {
			port.CellsSet(cx, cTcx0, evidence.GlGet(gl, g, evidence.ChX0()))
			port.CellsSet(cx, cTcy0, evidence.GlGet(gl, g, evidence.ChY0()))
			port.CellsSet(cx, cTcx1, evidence.GlGet(gl, g, evidence.ChX1()))
			port.CellsSet(cx, cTcy1, evidence.GlGet(gl, g, evidence.ChY1()))
		} else {
			if evidence.GlGet(gl, g, evidence.ChX0()) < port.CellsAt(cx, cTcx0) {
				port.CellsSet(cx, cTcx0, evidence.GlGet(gl, g, evidence.ChX0()))
			}
			if evidence.GlGet(gl, g, evidence.ChY0()) < port.CellsAt(cx, cTcy0) {
				port.CellsSet(cx, cTcy0, evidence.GlGet(gl, g, evidence.ChY0()))
			}
			if evidence.GlGet(gl, g, evidence.ChX1()) > port.CellsAt(cx, cTcx1) {
				port.CellsSet(cx, cTcx1, evidence.GlGet(gl, g, evidence.ChX1()))
			}
			if evidence.GlGet(gl, g, evidence.ChY1()) > port.CellsAt(cx, cTcy1) {
				port.CellsSet(cx, cTcy1, evidence.GlGet(gl, g, evidence.ChY1()))
			}
		}
		port.CellsSet(cx, cTcn, port.CellsAt(cx, cTcn)+1)
	}
	evidence.GlSet(gl, g, evidence.GfZ(), z)
	port.CellsSet(cx, cZ, z+1)
	evidence.GlSet(gl, g, evidence.GfMark(), port.CellsAt(cx, cMctop))
	evidence.GlSet(gl, g, evidence.GfOcg(), port.CellsAt(cx, cCurocg))
	if cnt > 1 {
		i = 0
		for i < cnt {
			idx = evidence.EtxAppendCp(et, PcPua(pcFCp(f0, f1, f2, f3, slot, i)))
			if i == 0 {
				tstart = idx
			}
			i += 1
		}
		evidence.GlSet(gl, g, evidence.ChTstart(), tstart)
		evidence.GlSet(gl, g, evidence.ChTlen(), cnt)
	}
	// The advance: tx = (w0 * Tfs + Tc + Tw) * Th, or ty = w1 * Tfs + Tc + Tw.
	var adv int64 = int64(0)
	if vert == 0 {
		adv = wfx + tc
	} else {
		adv = fx.FxMuldiv(int64(dwv), fs, int64(100000)) + tc
	}
	if (code == 32) && (ncode == 1) {
		adv = adv + tw
	}
	if vert == 0 {
		pcAdvance(cx, fx.FxMul(adv, th), int64(0))
	} else {
		pcAdvance(cx, int64(0), adv)
	}
	return 0
}

func pcShowStr(cx *port.Cells, ox *port.Cells, gl *port.Cells, et *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, s int32) int32 {
	// Show the string operand s: split it into codes by the font's codespace.
	var start int32 = pcEa(ox, s)
	var ln int32 = pcEb(ox, s)
	var slot int32 = port.CellsAt(cx, cSlot)
	var okfont int32 = 0
	var i int32 = 0
	var n int32 = 1
	var code int32 = 0
	var k int32 = 0
	var b0 int32 = 0
	var b1 int32 = -1
	var b2 int32 = -1
	var b3 int32 = -1
	if slot >= 0 {
		if port.CellsAt(cx, (cSlots+(slot*slotStride))+sStatus) == 0 {
			okfont = 1
		}
	}
	for i < ln {
		b0 = port.CellsAt(ox, start+i)
		b1 = -1
		b2 = -1
		b3 = -1
		if (i + 1) < ln {
			b1 = port.CellsAt(ox, start+(i+1))
		}
		if (i + 2) < ln {
			b2 = port.CellsAt(ox, start+(i+2))
		}
		if (i + 3) < ln {
			b3 = port.CellsAt(ox, start+(i+3))
		}
		n = 1
		if okfont == 1 {
			n = pcFCodeLen(f0, f1, f2, f3, slot, b0, b1, b2, b3)
		}
		if n < 1 {
			n = 1
		}
		if n > 4 {
			n = 4
		}
		if (i + n) > ln {
			n = ln - i
		}
		code = 0
		k = 0
		for k < n {
			if (n == 4) && ((k == 0) && (port.CellsAt(ox, start+i) >= 128)) {
				code = (port.CellsAt(ox, start+i) - 256) * 16777216
			} else {
				code = (code * 256) + port.CellsAt(ox, start+(i+k))
			}
			k += 1
		}
		pcGlyph(cx, gl, et, f0, f1, f2, f3, code, n)
		i += n
	}
	return 0
}

func pcShowArr(cx *port.Cells, ox *port.Cells, gl *port.Cells, et *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, s int32) int32 {
	// TJ: strings and adjustments. An adjustment n moves the position by
	// -n/1000 of the font size (along x, scaled by Th; along y in vertical mode).
	var cnt int32 = pcEa(ox, s)
	var slot int32 = port.CellsAt(cx, cSlot)
	var fs int64 = fx.FxGet(cx, cCur+gFs)
	var th int64 = fx.FxGet(cx, cCur+gTh)
	var vert int32 = 0
	var j int32 = s + 1
	var k int32 = 0
	var delta int64 = int64(0)
	if slot >= 0 {
		vert = port.CellsAt(cx, (cSlots+(slot*slotStride))+sVert)
	}
	for j < ((s + 1) + cnt) {
		k = pcKind(ox, j)
		if k == kStr {
			pcShowStr(cx, ox, gl, et, f0, f1, f2, f3, j)
		}
		if k == kNum {
			delta = int64(0) - fx.FxMuldiv(fx.FxMul(fx.FxJoin(pcEa(ox, j), pcEb(ox, j)), fs), int64(1), int64(1000))
			if vert == 0 {
				pcAdvance(cx, fx.FxMul(delta, th), int64(0))
			} else {
				pcAdvance(cx, int64(0), delta)
			}
		}
		j += pcEsize(ox, j)
	}
	return 0
}

var pcPdfdocTab [41]int32 = [41]int32{
	728, 711, 710, 729, 733, 731, 730, 732, 8226, 8224, 8225, 8230, 8212, 8211, 402, 8260,
	8249, 8250, 8722, 8240, 8222, 8220, 8221, 8216, 8217, 8218, 8482, 64257, 64258, 321, 338, 352,
	376, 381, 305, 322, 339, 353, 382, 65533, 8364,
}

func pcPdfdoc(c int32) int32 {
	// PDFDocEncoding (Annex D.2) to Unicode: Latin-1 except 0x18-0x1F, 0x80-0xA0.
	if (c >= 24) && (c <= 31) {
		return pcPdfdocTab[c-24]
	}
	if (c >= 128) && (c <= 160) {
		return pcPdfdocTab[8+(c-128)]
	}
	return c
}

func pcPushBytes(et *port.Cells, ox *port.Cells, start int32, ln int32) int32 {
	// A name's bytes as code points (Latin-1), into the evidence text. Answers
	// the index of the first.
	var at int32 = port.CellsLen(et)
	var k int32 = 0
	for k < ln {
		evidence.EtxAppendCp(et, port.CellsAt(ox, start+k))
		k += 1
	}
	return at
}

func pcPushEntry(et *port.Cells, ox *port.Cells, i int32) int32 {
	// The bytes of name operand i into the evidence text; the index of the first.
	var s int32 = pcEa(ox, i)
	var ln int32 = pcEb(ox, i)
	return pcPushBytes(et, ox, s, ln)
}

func pcPushUtf16(et *port.Cells, ox *port.Cells, start int32, ln int32, little int32) int32 {
	// UTF-16 text from ox[start, start+ln) (after the byte order mark), into
	// the evidence text: surrogate pairs joined, a lone surrogate U+FFFD, and
	// the language escapes of PDF 2.0 (U+001B ... U+001B) dropped.
	var k int32 = 0
	var u int32 = 0
	var u2 int32 = 0
	var skip int32 = 0
	for (k + 1) < ln {
		if little == 1 {
			u = port.CellsAt(ox, start+k) + (port.CellsAt(ox, start+(k+1)) * 256)
		} else {
			u = (port.CellsAt(ox, start+k) * 256) + port.CellsAt(ox, start+(k+1))
		}
		k += 2
		if (u >= 55296) && (u <= 56319) && ((k + 1) < ln) {
			if little == 1 {
				u2 = port.CellsAt(ox, start+k) + (port.CellsAt(ox, start+(k+1)) * 256)
			} else {
				u2 = (port.CellsAt(ox, start+k) * 256) + port.CellsAt(ox, start+(k+1))
			}
			if (u2 >= 56320) && (u2 <= 57343) {
				u = 65536 + (((u - 55296) * 1024) + (u2 - 56320))
				k += 2
			}
		}
		if u == 27 {
			skip = 1 - skip
		} else if skip == 0 {
			evidence.EtxAppendCp(et, u)
		}
	}
	return 0
}

func pcPushUtf8(et *port.Cells, ox *port.Cells, start int32, ln int32) int32 {
	var k int32 = 0
	var c int32 = 0
	var need int32 = 0
	var v int32 = 0
	var j int32 = 0
	var ok int32 = 0
	for k < ln {
		c = port.CellsAt(ox, start+k)
		k += 1
		need = 0
		v = c
		if c >= 240 {
			need = 3
			v = c - 240
		} else if c >= 224 {
			need = 2
			v = c - 224
		} else if c >= 192 {
			need = 1
			v = c - 192
		}
		ok = 1
		if (c >= 128) && (c < 192) {
			ok = 0
		}
		if c > 247 {
			ok = 0
		}
		j = 0
		for (ok == 1) && (j < need) {
			if (k < ln) && ((port.CellsAt(ox, start+k) >= 128) && (port.CellsAt(ox, start+k) < 192)) {
				v = (v * 64) + (port.CellsAt(ox, start+k) - 128)
				k += 1
			} else {
				ok = 0
			}
			j += 1
		}
		if ok == 1 {
			evidence.EtxAppendCp(et, v)
		} else {
			evidence.EtxAppendCp(et, 65533)
		}
	}
	return 0
}

func pcPushText(et *port.Cells, ox *port.Cells, start int32, ln int32) int32 {
	// A PDF text string (UTF-16BE or LE with a byte order mark, UTF-8 with its
	// BOM, else PDFDocEncoding) into the evidence text. Answers the first index.
	var at int32 = port.CellsLen(et)
	var k int32 = 0
	if (ln >= 2) && ((port.CellsAt(ox, start) == 254) && (port.CellsAt(ox, start+1) == 255)) {
		pcPushUtf16(et, ox, start+2, ln-2, 0)
		return at
	}
	if (ln >= 2) && ((port.CellsAt(ox, start) == 255) && (port.CellsAt(ox, start+1) == 254)) {
		pcPushUtf16(et, ox, start+2, ln-2, 1)
		return at
	}
	if (ln >= 3) && ((port.CellsAt(ox, start) == 239) && ((port.CellsAt(ox, start+1) == 187) && (port.CellsAt(ox, start+2) == 191))) {
		pcPushUtf8(et, ox, start+3, ln-3)
		return at
	}
	for k < ln {
		evidence.EtxAppendCp(et, pcPdfdoc(port.CellsAt(ox, start+k)))
		k += 1
	}
	return at
}

func pcArFx64(ar *port.Cells, h int32) int64 {
	var kind int32 = pdflex.PlKindOf(ar, h)
	if kind == 2 {
		return fx.FxOfInt(pdflex.PlIntValue(ar, h))
	}
	if kind == 3 {
		return fx.FxOfReal(pdflex.PlIntValue(ar, h), pdflex.PlRefGen(ar, h))
	}
	return int64(0)
}

func pcIngestProps(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, dict int32) int32 {
	// Copy the pairs of a /Properties dictionary that marked content reads
	// into the operand entries as a dictionary entry, so one reader serves an
	// inline property list and a named one. Answers the entry's index.
	var d int32 = pcOxPush(cx, ox, kDict, 0, 0, 0)
	var k int32 = pdflex.PlFirst(ar, dict)
	var v int32 = 0
	var vr int32 = 0
	var want int32 = 0
	var kind int32 = 0
	var at int32 = 0
	var j int32 = 0
	var ln int32 = 0
	var fxv int64 = int64(0)
	if d < 0 {
		return -1
	}
	for k != 0 {
		v = pdflex.PlNext(ar, k)
		want = 0
		if pdflex.PlKindOf(ar, k) == 4 {
			if (pdflex.PlNameIs(ar, k, pdfnames.PnMcid()) == 1) || ((pdflex.PlNameIs(ar, k, pdfnames.PnActualText()) == 1) || ((pdflex.PlNameIs(ar, k, pdfnames.PnAlt()) == 1) || ((pdflex.PlNameIs(ar, k, pdfnames.PnE()) == 1) || ((pdflex.PlNameIs(ar, k, pdfnames.PnLang()) == 1) || ((pdflex.PlNameIs(ar, k, pdfnames.PnType()) == 1) || (pdflex.PlNameIs(ar, k, pdfnames.PnSubtype()) == 1)))))) {
				want = 1
			}
		}
		if (want == 1) && (v != 0) {
			vr = pdfdoc.PdResolve(src, ar, dc, a, b, st, v)
			kind = 0
			if vr != 0 {
				kind = pdflex.PlKindOf(ar, vr)
			}
			if (kind == 2) || (kind == 3) {
				fxv = pcArFx64(ar, vr)
				// The key, then the number.
				ln = pdflex.PlNameLen(ar, k)
				at = port.CellsLen(ox)
				j = 0
				for j < ln {
					port.CellsPush(ox, pdflex.PlNameByte(ar, k, j))
					j += 1
				}
				pcOxPush(cx, ox, kName, at, ln, 0)
				pcOxPush(cx, ox, kNum, fx.FxHi(fxv), fx.FxLo(fxv), 1)
			}
			if (kind == 4) || (kind == 5) {
				ln = pdflex.PlNameLen(ar, k)
				at = port.CellsLen(ox)
				j = 0
				for j < ln {
					port.CellsPush(ox, pdflex.PlNameByte(ar, k, j))
					j += 1
				}
				pcOxPush(cx, ox, kName, at, ln, 0)
				ln = pdflex.PlStrLen(ar, vr)
				at = port.CellsLen(ox)
				j = 0
				if kind == 4 {
					for j < ln {
						port.CellsPush(ox, pdflex.PlNameByte(ar, vr, j))
						j += 1
					}
				} else {
					for j < ln {
						port.CellsPush(ox, pdflex.PlStrByte(ar, vr, j))
						j += 1
					}
				}
				if kind == 4 {
					pcOxPush(cx, ox, kName, at, ln, 0)
				} else {
					pcOxPush(cx, ox, kStr, at, ln, 0)
				}
			}
		}
		if v == 0 {
			k = 0
		} else {
			k = pdflex.PlNext(ar, v)
		}
	}
	port.CellsSet(ox, (d*4)+1, (port.CellsAt(cx, cOxn)-d)-1)
	return d
}

func pcReadProps(et *port.Cells, mk *port.Cells, ox *port.Cells, span int32, d int32, isart int32) int32 {
	// Fill the mark's fields from the dictionary entry d of the operands: MCID, ActualText, Alt, E, Lang;
	// and, for an /Artifact, its /Type and /Subtype as codes (`ar`: pagination, layout, background, page,
	// else `other`; `as`: header, footer, watermark, else `other`). A name that is none of the known ones
	// is not kept (SPEC 8.4.3 holds codes, D101 held the name).
	var end int32 = (d + 1) + pcEa(ox, d)
	var j int32 = d + 1
	var v int32 = 0
	var ks int32 = 0
	var kl int32 = 0
	var vs int32 = 0
	var vl int32 = 0
	var vk int32 = 0
	var at int32 = 0
	for j < end {
		v = j + 1
		if (pcKind(ox, j) == kName) && (v < end) {
			ks = pcEa(ox, j)
			kl = pcEb(ox, j)
			vk = pcKind(ox, v)
			vs = pcEa(ox, v)
			vl = pcEb(ox, v)
			if (pcNameEq(ox, ks, kl, pdfnames.PnMcid()) == 1) && (vk == kNum) {
				evidence.MkSet(mk, span, evidence.MkfMcid(), fx.FxRound(fx.FxJoin(vs, vl)))
			}
			if (isart == 1) && ((pcNameEq(ox, ks, kl, pdfnames.PnType()) == 1) && (vk == kName)) {
				evidence.MkSet(mk, span, evidence.MkfArtype(), evidence.ArOther())
				if pcNameEq(ox, vs, vl, pdfnames.PnPagination()) == 1 {
					evidence.MkSet(mk, span, evidence.MkfArtype(), evidence.ArPagination())
				}
				if pcNameEq(ox, vs, vl, pdfnames.PnLayout()) == 1 {
					evidence.MkSet(mk, span, evidence.MkfArtype(), evidence.ArLayout())
				}
				if pcNameEq(ox, vs, vl, pdfnames.PnBackground()) == 1 {
					evidence.MkSet(mk, span, evidence.MkfArtype(), evidence.ArBackground())
				}
				if pcNameEq(ox, vs, vl, pdfnames.PnPage()) == 1 {
					evidence.MkSet(mk, span, evidence.MkfArtype(), evidence.ArPage())
				}
			}
			if (isart == 1) && ((pcNameEq(ox, ks, kl, pdfnames.PnSubtype()) == 1) && (vk == kName)) {
				evidence.MkSet(mk, span, evidence.MkfArsub(), evidence.AsOther())
				if pcNameEq(ox, vs, vl, pdfnames.PnHeader()) == 1 {
					evidence.MkSet(mk, span, evidence.MkfArsub(), evidence.AsHeader())
				}
				if pcNameEq(ox, vs, vl, pdfnames.PnFooter()) == 1 {
					evidence.MkSet(mk, span, evidence.MkfArsub(), evidence.AsFooter())
				}
				if pcNameEq(ox, vs, vl, pdfnames.PnWatermark()) == 1 {
					evidence.MkSet(mk, span, evidence.MkfArsub(), evidence.AsWatermark())
				}
			}
			if (vk == kStr) || (vk == kName) {
				if pcNameEq(ox, ks, kl, pdfnames.PnActualText()) == 1 {
					at = pcPushText(et, ox, vs, vl)
					evidence.MkSet(mk, span, evidence.MkfActual(), at)
					evidence.MkSet(mk, span, evidence.MkfActuallen(), port.CellsLen(et)-at)
				}
				if pcNameEq(ox, ks, kl, pdfnames.PnAlt()) == 1 {
					at = pcPushText(et, ox, vs, vl)
					evidence.MkSet(mk, span, evidence.MkfAlt(), at)
					evidence.MkSet(mk, span, evidence.MkfAltlen(), port.CellsLen(et)-at)
				}
				if pcNameEq(ox, ks, kl, pdfnames.PnE()) == 1 {
					at = pcPushText(et, ox, vs, vl)
					evidence.MkSet(mk, span, evidence.MkfExp(), at)
					evidence.MkSet(mk, span, evidence.MkfExplen(), port.CellsLen(et)-at)
				}
				if pcNameEq(ox, ks, kl, pdfnames.PnLang()) == 1 {
					at = pcPushText(et, ox, vs, vl)
					evidence.MkSet(mk, span, evidence.MkfLang(), at)
					evidence.MkSet(mk, span, evidence.MkfLanglen(), port.CellsLen(et)-at)
				}
			}
			j = v + pcEsize(ox, v)
		} else {
			j += pcEsize(ox, j)
		}
	}
	return 0
}

func pcMcPop(cx *port.Cells, mk *port.Cells, gl *port.Cells, unterminated int32) int32 {
	// Close the innermost open mark: its glyphs are those shown since it opened, its painted objects
	// those numbered since (`mk-close`).
	var t int32 = port.CellsAt(cx, cMctop)
	if t < 0 {
		return 0
	}
	var g int32 = evidence.GlCount(gl)
	var par int32 = evidence.MkGet(mk, t, evidence.MkfParent())
	evidence.MkClose(mk, t, g, port.CellsAt(cx, cZ))
	if unterminated == 1 {
		var fl int32 = evidence.MkGet(mk, t, evidence.MkfFlags())
		evidence.MkSet(mk, t, evidence.MkfFlags(), fl|evidence.McUnterminated())
	}
	port.CellsSet(cx, cMctop, par)
	port.CellsSet(cx, cMcdepth, port.CellsAt(cx, cMcdepth)-1)
	if port.CellsAt(cx, cCurocg) == t {
		port.CellsSet(cx, cCurocg, evidence.MkOcgOf(mk, par))
	}
	return 0
}

func pcMcBegin(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, gl *port.Cells, et *port.Cells, mk *port.Cells, fnt *port.Cells, gx *port.Cells, n int32, props int32) int32 {
	// BMC / BDC: open a mark with the tag of operand 0 and, for BDC, the properties of operand 1 (an
	// inline dictionary, or a name in /Properties). Its kind is `artifact` for /Artifact,
	// `optional-content` for /OC (its object number is the /Properties entry's, when that is a
	// reference), else `tag`.
	var depth int32 = port.CellsAt(cx, cMcdepth)
	var tstart int32 = 0
	var tlen int32 = 0
	var span int32 = 0
	var d int32 = -1
	var raw int32 = 0
	var dh int32 = 0
	var isart int32 = 0
	var isoc int32 = 0
	var t0 int32 = 0
	var kind int32 = 3
	var flags int32 = 0
	if depth >= maxMc {
		port.CellsSet(cx, cMcover, port.CellsAt(cx, cMcover)+1)
		pcWarnSet(cx, wMc)
		return 0
	}
	tstart = port.CellsLen(et)
	if (n >= 1) && (pcKind(ox, 0) == kName) {
		tstart = pcPushEntry(et, ox, 0)
		tlen = pcEb(ox, 0)
		if pcEntryNameIs(ox, 0, pdfnames.PnArtifact()) == 1 {
			isart = 1
		}
		t0 = pcEa(ox, 0)
		if (tlen == 2) && ((port.CellsAt(ox, t0) == 79) && (port.CellsAt(ox, t0+1) == 67)) {
			isoc = 1
		}
	}
	if isart == 1 {
		kind = evidence.MkArtifact()
	}
	if isoc == 1 {
		kind = evidence.MkOptionalContent()
	}
	span = evidence.MkOpen(mk, port.CellsAt(cx, cPage), kind, tstart, tlen, port.CellsAt(cx, cMctop), evidence.GlCount(gl), port.CellsAt(cx, cZ))
	evidence.MkSet(mk, span, evidence.MkfStm(), port.CellsAt(cx, cStm))
	if isart == 1 {
		evidence.MkSet(mk, span, evidence.MkfArtype(), evidence.ArOther())
	}
	if (props == 1) && (n >= 2) {
		if pcKind(ox, 1) == kDict {
			d = 1
			flags = evidence.McInline()
		}
		if pcKind(ox, 1) == kName {
			raw = pcResEntry(src, ar, dc, a, b, st, cx, ox, pdfnames.PnProperties(), 1)
			if raw != 0 {
				dh = pdfdoc.PdResolve(src, ar, dc, a, b, st, raw)
			}
			if pdfsrc.PsMissed(src) {
				port.CellsSet(cx, cAbort, 1)
			}
			if (isoc == 1) && (raw != 0) {
				if pdflex.PlKindOf(ar, raw) == 9 {
					evidence.MkSet(mk, span, evidence.MkfOcg(), pdflex.PlIntValue(ar, raw))
				}
				evidence.MkSet(mk, span, evidence.MkfOcgdef(), pdfgfx.GxOcState(src, ar, dc, a, b, st, gx, raw, 0))
			}
			if (dh != 0) && (pdflex.PlKindOf(ar, dh) == 7) {
				d = pcIngestProps(src, ar, dc, a, b, st, cx, ox, dh)
				flags = evidence.McResource()
			} else {
				flags = evidence.McUnresolved()
				pcWarnSet(cx, wProps)
			}
		}
		evidence.MkSet(mk, span, evidence.MkfFlags(), flags)
		if d >= 0 {
			pcReadProps(et, mk, ox, span, d, isart)
		}
	}
	port.CellsSet(cx, cMctop, span)
	port.CellsSet(cx, cMcdepth, depth+1)
	if isoc == 1 {
		port.CellsSet(cx, cCurocg, span)
	}
	return 0
}

func pcMcEnd(cx *port.Cells, mk *port.Cells, gl *port.Cells) int32 {
	// EMC: close the innermost mark this stream opened; a BDC that was too deep
	// to record is balanced first; an EMC with nothing to close is ignored.
	var over int32 = port.CellsAt(cx, cMcover)
	if over > 0 {
		port.CellsSet(cx, cMcover, over-1)
		return 0
	}
	if port.CellsAt(cx, cMcdepth) <= port.CellsAt(cx, cMcbase) {
		pcWarnSet(cx, wMc)
		return 0
	}
	return pcMcPop(cx, mk, gl, 0)
}

func pcSkipInline(cx *port.Cells, cs *port.Cells) int32 {
	// BI: skip to the end of the inline image: find `ID` and its one white
	// space, then the first `EI` that stands alone (white space before and white
	// space or the end after). Binary data rarely contains one; if it does the
	// rest is read as operators and skipped as unknown ones.
	var end int32 = port.CellsAt(cx, cEnd)
	var p int32 = port.CellsAt(cx, cPos)
	var found int32 = 0
	for ((p + 2) < end) && (found == 0) {
		if (pcWs(port.CellsAt(cs, p)) == 1) && ((port.CellsAt(cs, p+1) == 73) && ((port.CellsAt(cs, p+2) == 68) && (((p + 3) >= end) || (pcWs(port.CellsAt(cs, p+3)) == 1)))) {
			found = 1
			p += 4
		} else {
			p += 1
		}
	}
	if found == 0 {
		port.CellsSet(cx, cPos, end)
		return 0
	}
	found = 0
	for ((p + 1) < end) && (found == 0) {
		if (port.CellsAt(cs, p) == 69) && ((port.CellsAt(cs, p+1) == 73) && (((p == 0) || (pcWs(port.CellsAt(cs, p-1)) == 1)) && (((p + 2) >= end) || (pcWs(port.CellsAt(cs, p+2)) == 1)))) {
			found = 1
			p += 2
		} else {
			p += 1
		}
	}
	if found == 0 {
		p = end
	}
	port.CellsSet(cx, cPos, p)
	return 0
}

func pcTx(cx *port.Cells, x int64, y int64) int64 {
	// The user-space point (x, y) in page space: x of it (Fx).
	return fx.FxClamp(fx.MxX(cx, cCur+gCtm, x, y))
}

func pcTy(cx *port.Cells, x int64, y int64) int64 {
	return fx.FxClamp(fx.MxY(cx, cCur+gCtm, x, y))
}

func pcFlagOr(v int32, bit int32) int32 {
	// v with the one-bit flag `bit` set.
	if (v & bit) != 0 {
		return v
	}
	return v + bit
}

func pcPathReset(cx *port.Cells, pts *port.Cells) int32 {
	// No path: the next point starts one. The pts arena keeps what an earlier row of the evidence put there.
	var n int32 = evidence.PtCount(pts)
	port.CellsSet(cx, cPpts, n)
	port.CellsSet(cx, cPn, 0)
	port.CellsSet(cx, cPkeep, 0)
	port.CellsSet(cx, cPbx0, 2147483647)
	port.CellsSet(cx, cPby0, 2147483647)
	port.CellsSet(cx, cPbx1, -2147483647)
	port.CellsSet(cx, cPby1, -2147483647)
	port.CellsSet(cx, cPflags, 0)
	port.CellsSet(cx, cPnsub, 0)
	return 0
}

func pcPathAdd(cx *port.Cells, pts *port.Cells, px int64, py int64, op int32) int32 {
	// Append the page-space point (px, py) to the path: its box, the current point, and (for the first
	// PATH_KEEP points) a row of `pts`.
	var x int32 = fx.FxRound(px)
	var y int32 = fx.FxRound(py)
	var keep int32 = port.CellsAt(cx, cPkeep)
	if x < port.CellsAt(cx, cPbx0) {
		port.CellsSet(cx, cPbx0, x)
	}
	if y < port.CellsAt(cx, cPby0) {
		port.CellsSet(cx, cPby0, y)
	}
	if x > port.CellsAt(cx, cPbx1) {
		port.CellsSet(cx, cPbx1, x)
	}
	if y > port.CellsAt(cx, cPby1) {
		port.CellsSet(cx, cPby1, y)
	}
	if (keep < pathKeepStraight) && ((evidence.PtCount(pts) - port.CellsAt(cx, cPts0)) < ptsPage) {
		evidence.PtAdd(pts, x, y, op)
		port.CellsSet(cx, cPkeep, keep+1)
	} else {
		if keep < pathKeepStraight {
			pcWarnSet(cx, wPaths)
		}
		port.CellsSet(cx, cPflags, pcFlagOr(port.CellsAt(cx, cPflags), 4))
	}
	port.CellsSet(cx, cPn, port.CellsAt(cx, cPn)+1)
	fx.FxPut(cx, cPcx, px)
	fx.FxPut(cx, cPcy, py)
	return 0
}

func pcOpMove(cx *port.Cells, pts *port.Cells, ox *port.Cells, n int32) int32 {
	if n < 2 {
		return 0
	}
	var x int64 = pcNum(ox, n, 0)
	var y int64 = pcNum(ox, n, 1)
	var px int64 = pcTx(cx, x, y)
	var py int64 = pcTy(cx, x, y)
	port.CellsSet(cx, cPnsub, port.CellsAt(cx, cPnsub)+1)
	pcPathAdd(cx, pts, px, py, evidence.PoMove())
	fx.FxPut(cx, cPsx, px)
	fx.FxPut(cx, cPsy, py)
	return 0
}

func pcOpLine(cx *port.Cells, pts *port.Cells, ox *port.Cells, n int32) int32 {
	if n < 2 {
		return 0
	}
	if port.CellsAt(cx, cPn) == 0 {
		return 0
	}
	var x int64 = pcNum(ox, n, 0)
	var y int64 = pcNum(ox, n, 1)
	var px int64 = pcTx(cx, x, y)
	var py int64 = pcTy(cx, x, y)
	pcPathAdd(cx, pts, px, py, evidence.PoLine())
	return 0
}

func pcOpCurve(cx *port.Cells, pts *port.Cells, ox *port.Cells, n int32, kind int32) int32 {
	// c (kind 0, six numbers), v (kind 1: the first control point is the current point) and y (kind 2: the
	// second control point is the end point). Each puts three curve points in the path.
	if port.CellsAt(cx, cPn) == 0 {
		return 0
	}
	var x1 int64 = int64(0)
	var y1 int64 = int64(0)
	var x2 int64 = int64(0)
	var y2 int64 = int64(0)
	var x3 int64 = int64(0)
	var y3 int64 = int64(0)
	var q1x int64 = int64(0)
	var q1y int64 = int64(0)
	if kind == 0 {
		if n < 6 {
			return 0
		}
		x1 = pcNum(ox, n, 0)
		y1 = pcNum(ox, n, 1)
		x2 = pcNum(ox, n, 2)
		y2 = pcNum(ox, n, 3)
		x3 = pcNum(ox, n, 4)
		y3 = pcNum(ox, n, 5)
	}
	if kind == 1 {
		if n < 4 {
			return 0
		}
		x2 = pcNum(ox, n, 0)
		y2 = pcNum(ox, n, 1)
		x3 = pcNum(ox, n, 2)
		y3 = pcNum(ox, n, 3)
	}
	if kind == 2 {
		if n < 4 {
			return 0
		}
		x1 = pcNum(ox, n, 0)
		y1 = pcNum(ox, n, 1)
		x3 = pcNum(ox, n, 2)
		y3 = pcNum(ox, n, 3)
		x2 = x3
		y2 = y3
	}
	if kind == 1 {
		q1x = fx.FxGet(cx, cPcx)
		q1y = fx.FxGet(cx, cPcy)
	} else {
		q1x = pcTx(cx, x1, y1)
		q1y = pcTy(cx, x1, y1)
	}
	pcPathAdd(cx, pts, q1x, q1y, evidence.PoCurve())
	var q2x int64 = pcTx(cx, x2, y2)
	var q2y int64 = pcTy(cx, x2, y2)
	var q3x int64 = pcTx(cx, x3, y3)
	var q3y int64 = pcTy(cx, x3, y3)
	pcPathAdd(cx, pts, q2x, q2y, evidence.PoCurve())
	pcPathAdd(cx, pts, q3x, q3y, evidence.PoCurve())
	port.CellsSet(cx, cPflags, pcFlagOr(port.CellsAt(cx, cPflags), 1))
	return 0
}

func pcOpClose(cx *port.Cells, pts *port.Cells) int32 {
	// h: a close row at the subpath's start, which is the current point again.
	if port.CellsAt(cx, cPn) == 0 {
		return 0
	}
	var sx int64 = fx.FxGet(cx, cPsx)
	var sy int64 = fx.FxGet(cx, cPsy)
	pcPathAdd(cx, pts, sx, sy, evidence.PoClose())
	return 0
}

func pcRectPath(cx *port.Cells, pts *port.Cells, x int64, y int64, w int64, h int64) int32 {
	// The rectangle x y w h (user space) as a closed subpath of four corners, each through the CTM.
	var xw int64 = fx.FxClamp(x + w)
	var yh int64 = fx.FxClamp(y + h)
	var ax int64 = pcTx(cx, x, y)
	var ay int64 = pcTy(cx, x, y)
	var bx int64 = pcTx(cx, xw, y)
	var by int64 = pcTy(cx, xw, y)
	var dx int64 = pcTx(cx, xw, yh)
	var dy int64 = pcTy(cx, xw, yh)
	var ex int64 = pcTx(cx, x, yh)
	var ey int64 = pcTy(cx, x, yh)
	port.CellsSet(cx, cPnsub, port.CellsAt(cx, cPnsub)+1)
	pcPathAdd(cx, pts, ax, ay, evidence.PoMove())
	fx.FxPut(cx, cPsx, ax)
	fx.FxPut(cx, cPsy, ay)
	pcPathAdd(cx, pts, bx, by, evidence.PoLine())
	pcPathAdd(cx, pts, dx, dy, evidence.PoLine())
	pcPathAdd(cx, pts, ex, ey, evidence.PoLine())
	pcPathAdd(cx, pts, ax, ay, evidence.PoClose())
	return 0
}

func pcOpRect(cx *port.Cells, pts *port.Cells, ox *port.Cells, n int32) int32 {
	// re: the rectangle x y w h.
	if n < 4 {
		return 0
	}
	var x int64 = pcNum(ox, n, 0)
	var y int64 = pcNum(ox, n, 1)
	var w int64 = pcNum(ox, n, 2)
	var h int64 = pcNum(ox, n, 3)
	pcRectPath(cx, pts, x, y, w, h)
	return 0
}

func pcNear(p int32, q int32) int32 {
	// 1 when two centipoint coordinates differ by at most one (a corner rounded two ways).
	var d int32 = p - q
	if (d <= 1) && (d >= -1) {
		return 1
	}
	return 0
}

func pcIsRect(cx *port.Cells, pts *port.Cells) int32 {
	// 1 when the path is one subpath of four corners (a line back to the first corner, and a close, allowed)
	// whose sides are axis-aligned to a centipoint.
	var n int32 = port.CellsAt(cx, cPn)
	var s int32 = port.CellsAt(cx, cPpts)
	var k int32 = 0
	var np int32 = 0
	var opk int32 = 0
	var x0 int32 = 0
	var y0 int32 = 0
	var x1 int32 = 0
	var y1 int32 = 0
	var x2 int32 = 0
	var y2 int32 = 0
	var x3 int32 = 0
	var y3 int32 = 0
	var px int32 = 0
	var py int32 = 0
	if (n < 4) || (n > 6) {
		return 0
	}
	if port.CellsAt(cx, cPnsub) != 1 {
		return 0
	}
	if (port.CellsAt(cx, cPflags) & 5) != 0 {
		return 0
	}
	// The points that are not a close row, in order; the first must be a move.
	for k < n {
		opk = evidence.PtGet(pts, s+k, evidence.PtfOp())
		px = evidence.PtGet(pts, s+k, evidence.PtfX())
		py = evidence.PtGet(pts, s+k, evidence.PtfY())
		if k == 0 {
			if opk != evidence.PoMove() {
				return 0
			}
		}
		if (k > 0) && (opk == evidence.PoMove()) {
			return 0
		}
		if opk != evidence.PoClose() {
			if np == 0 {
				x0 = px
				y0 = py
			}
			if np == 1 {
				x1 = px
				y1 = py
			}
			if np == 2 {
				x2 = px
				y2 = py
			}
			if np == 3 {
				x3 = px
				y3 = py
			}
			if np == 4 {
				if (pcNear(px, x0) == 0) || (pcNear(py, y0) == 0) {
					return 0
				}
			}
			np += 1
		}
		k += 1
	}
	if (np != 4) && (np != 5) {
		return 0
	}
	if (pcNear(x0, x1) == 1) && ((pcNear(y1, y2) == 1) && ((pcNear(x2, x3) == 1) && (pcNear(y3, y0) == 1))) {
		return 1
	}
	if (pcNear(y0, y1) == 1) && ((pcNear(x1, x2) == 1) && ((pcNear(y2, y3) == 1) && (pcNear(x3, x0) == 1))) {
		return 1
	}
	return 0
}

func pcScaleCpt(cx *port.Cells, w int64) int32 {
	// A length in user units (an Fx) as centipoints under the current CTM: through the length of its x axis.
	var a int64 = fx.FxGet(cx, cCur+gCtm)
	var b int64 = fx.FxGet(cx, (cCur+gCtm)+2)
	var hyp int64 = fx.FxHypot(a, b)
	var v int32 = fx.FxRound(fx.FxMul(fx.FxAbs(w), hyp))
	if v > 10000000 {
		return 10000000
	}
	return v
}

func pcDashOp(cx *port.Cells, ox *port.Cells, n int32) int32 {
	// d: the dash array's first length (centipoints under the CTM), 0 for a solid line.
	port.CellsSet(cx, cCur+gDash, 0)
	if n < 1 {
		return 0
	}
	if pcKind(ox, 0) != kArr {
		return 0
	}
	if pcEa(ox, 0) < 1 {
		return 0
	}
	if pcKind(ox, 1) != kNum {
		return 0
	}
	var v int64 = pcNum(ox, n, 1)
	var sc int32 = pcScaleCpt(cx, v)
	port.CellsSet(cx, cCur+gDash, sc)
	return 0
}

func pcClipBox(cx *port.Cells, pa *port.Cells, x0 int32, y0 int32, x1 int32, y1 int32, kind int32, flags int32, pfirst int32, pcount int32) int32 {
	// Clip to the box (x0, y0, x1, y1) of a shape of `kind`: the region becomes its intersection with the clip in
	// force. When that does not shrink the region there is nothing to record; else a `paths` row (a clip, SPEC
	// 8.4.3: z -1) holds the intersection, naming the clip it was cut from, and becomes the clip in force.
	var cur int32 = port.CellsAt(cx, cCur+gClip)
	var ix0 int32 = x0
	var iy0 int32 = y0
	var ix1 int32 = x1
	var iy1 int32 = y1
	var same int32 = 0
	var cb int32 = 0
	var r int32 = 0
	if cur >= 0 {
		cb = evidence.PaGet(pa, cur, evidence.PfX0())
		if cb > ix0 {
			ix0 = cb
		}
		cb = evidence.PaGet(pa, cur, evidence.PfY0())
		if cb > iy0 {
			iy0 = cb
		}
		cb = evidence.PaGet(pa, cur, evidence.PfX1())
		if cb < ix1 {
			ix1 = cb
		}
		cb = evidence.PaGet(pa, cur, evidence.PfY1())
		if cb < iy1 {
			iy1 = cb
		}
		if (ix0 == evidence.PaGet(pa, cur, evidence.PfX0())) && ((iy0 == evidence.PaGet(pa, cur, evidence.PfY0())) && ((ix1 == evidence.PaGet(pa, cur, evidence.PfX1())) && (iy1 == evidence.PaGet(pa, cur, evidence.PfY1())))) {
			same = 1
		}
	}
	if same == 1 {
		return 0
	}
	if port.CellsAt(cx, cNpath) >= pathRows {
		pcWarnSet(cx, wPaths)
		return 0
	}
	r = evidence.PaNew(pa, port.CellsAt(cx, cPage), kind, ix0, iy0, ix1, iy1)
	evidence.PaSet(pa, r, evidence.PfFlags(), evidence.PgClip()+flags)
	evidence.PaSet(pa, r, evidence.PfClip(), cur)
	evidence.PaSet(pa, r, evidence.PfMark(), port.CellsAt(cx, cMctop))
	evidence.PaSet(pa, r, evidence.PfOcg(), port.CellsAt(cx, cCurocg))
	evidence.PaSet(pa, r, evidence.PfPfirst(), pfirst)
	evidence.PaSet(pa, r, evidence.PfPcount(), pcount)
	port.CellsSet(cx, cNpath, port.CellsAt(cx, cNpath)+1)
	port.CellsSet(cx, cCur+gClip, r)
	return 0
}

func pcKindOfPath(cx *port.Cells, pts *port.Cells) int32 {
	// The `pa` kind of the path: a rectangle, a curve, a single line, else other.
	if pcIsRect(cx, pts) == 1 {
		return evidence.PaRect()
	}
	if (port.CellsAt(cx, cPflags) & 1) != 0 {
		return evidence.PaCurve()
	}
	if (port.CellsAt(cx, cPn) == 2) && (port.CellsAt(cx, cPnsub) == 1) {
		return evidence.PaLine()
	}
	return evidence.PaOther()
}

func pcGeomKept(cx *port.Cells) int32 {
	// 1 when the whole path is in `pts`: a path of `m l h re` alone had no more than PATH_KEEP_STRAIGHT points (and the
	// page's `pts` was not full), a path with a curve no more than PATH_KEEP (D219).
	if (port.CellsAt(cx, cPflags) & 4) != 0 {
		return 0
	}
	if ((port.CellsAt(cx, cPflags) & 1) != 0) && (port.CellsAt(cx, cPn) > pathKeep) {
		return 0
	}
	return 1
}

func pcEndPath(cx *port.Cells, pa *port.Cells, pts *port.Cells, fill int32, stroke int32, evenodd int32, closed int32) int32 {
	// A paint operator (or `n`) ends the path. If it filled or stroked, a `paths` row records it; then a pending
	// `W` or `W*` clips to it. The row's box is the path's box, grown by half the stroke width when it strokes;
	// its geometry is the path's rows of `pts` (kept when the path was short enough, else dropped).
	var n int32 = port.CellsAt(cx, cPn)
	var start int32 = port.CellsAt(cx, cPpts)
	var kept int32 = pcGeomKept(cx)
	var pend int32 = port.CellsAt(cx, cClipp)
	var kind int32 = 0
	var half int32 = 0
	var r int32 = 0
	var fl int32 = 0
	var wd int32 = 0
	var lwv int64 = int64(0)
	var nrows int32 = 0
	var pfst int32 = -1
	var geom int32 = 0
	var painted int32 = 0
	var tr int32 = 0
	port.CellsSet(cx, cClipp, 0)
	if n == 0 {
		pcPathReset(cx, pts)
		return 0
	}
	kind = pcKindOfPath(cx, pts)
	nrows = n
	if kept == 0 {
		nrows = 0
	}
	if kept == 0 {
		tr = evidence.PgTruncated()
	}
	if nrows > 0 {
		pfst = start
	}
	if (kept == 0) && (port.CellsAt(cx, cPkeep) > 0) {
		port.CellsDrop(pts, start*3)
	}
	geom = nrows
	if (fill == 1) || (stroke == 1) {
		if port.CellsAt(cx, cNpath) >= pathRows {
			pcWarnSet(cx, wPaths)
		} else {
			painted = 1
			fl = tr
			if closed != 0 {
				fl += evidence.PgClosed()
			}
			if evenodd == 1 {
				fl += evidence.PgEvenodd()
			}
			if stroke == 1 {
				lwv = fx.FxGet(cx, cCur+gLw)
				wd = pcScaleCpt(cx, lwv)
				half = (wd + 1) / 2
				fl += evidence.PgStroked()
			}
			if fill == 1 {
				fl += evidence.PgFilled()
				if port.CellsAt(cx, cCur+gFam) == 5 {
					fl += evidence.PgPattern()
				}
			}
			if port.CellsAt(cx, cCur+gBm) != 0 {
				fl += evidence.PgBlend()
			}
			if port.CellsAt(cx, cCur+gSmask) != 0 {
				fl += evidence.PgSoftmask()
			}
			r = evidence.PaNew(pa, port.CellsAt(cx, cPage), kind, port.CellsAt(cx, cPbx0)-half, port.CellsAt(cx, cPby0)-half, port.CellsAt(cx, cPbx1)+half, port.CellsAt(cx, cPby1)+half)
			evidence.PaSet(pa, r, evidence.PfFlags(), fl)
			if fill == 1 {
				evidence.PaSet(pa, r, evidence.PfFill(), port.CellsAt(cx, cCur+gColor))
			}
			if stroke == 1 {
				evidence.PaSet(pa, r, evidence.PfStroke(), port.CellsAt(cx, cCur+gScolor))
				evidence.PaSet(pa, r, evidence.PfWidth(), wd)
				evidence.PaSet(pa, r, evidence.PfDash(), port.CellsAt(cx, cCur+gDash))
			}
			evidence.PaSet(pa, r, evidence.PfFalpha(), port.CellsAt(cx, cCur+gAlpha))
			evidence.PaSet(pa, r, evidence.PfSalpha(), port.CellsAt(cx, cCur+gSalpha))
			evidence.PaSet(pa, r, evidence.PfZ(), port.CellsAt(cx, cZ))
			port.CellsSet(cx, cZ, port.CellsAt(cx, cZ)+1)
			evidence.PaSet(pa, r, evidence.PfClip(), port.CellsAt(cx, cCur+gClip))
			evidence.PaSet(pa, r, evidence.PfMark(), port.CellsAt(cx, cMctop))
			evidence.PaSet(pa, r, evidence.PfOcg(), port.CellsAt(cx, cCurocg))
			evidence.PaSet(pa, r, evidence.PfPfirst(), pfst)
			evidence.PaSet(pa, r, evidence.PfPcount(), geom)
			port.CellsSet(cx, cNpath, port.CellsAt(cx, cNpath)+1)
		}
	}
	if pend != 0 {
		fl = tr
		if pend == 2 {
			fl += evidence.PgEvenodd()
		}
		pcClipBox(cx, pa, port.CellsAt(cx, cPbx0), port.CellsAt(cx, cPby0), port.CellsAt(cx, cPbx1), port.CellsAt(cx, cPby1), kind, fl, pfst, geom)
	}
	// A path whose geometry nobody kept leaves no rows behind.
	if (painted == 0) && (pend == 0) {
		port.CellsDrop(pts, start*3)
	}
	pcPathReset(cx, pts)
	return 0
}

func pcPaintOp(cx *port.Cells, pa *port.Cells, pts *port.Cells, op int32) int32 {
	// S s f F f* B B* b b* n: which of fill, stroke, even-odd and close each one means.
	var fill int32 = 0
	var stroke int32 = 0
	var eo int32 = 0
	var shut int32 = 0
	if op == opStroke {
		stroke = 1
	}
	if op == opClosestroke {
		stroke = 1
		shut = 1
	}
	if (op == opFill) || (op == opFill2) {
		fill = 1
	}
	if op == opFilleo {
		fill = 1
		eo = 1
	}
	if op == opFs {
		fill = 1
		stroke = 1
	}
	if op == opFseo {
		fill = 1
		stroke = 1
		eo = 1
	}
	if op == opCfs {
		fill = 1
		stroke = 1
		shut = 1
	}
	if op == opCfseo {
		fill = 1
		stroke = 1
		shut = 1
		eo = 1
	}
	if shut == 1 {
		pcOpClose(cx, pts)
	}
	pcEndPath(cx, pa, pts, fill, stroke, eo, shut)
	return 0
}

func pcSetInk(cx *port.Cells, stroke int32, key int32, cls int32, rgb int32) int32 {
	// Make (key, class, colour) the fill (stroke 0) or stroking (stroke 1) colour of the current state.
	if stroke == 1 {
		port.CellsSet(cx, cCur+gScs, key)
		port.CellsSet(cx, cCur+gSfam, cls)
		port.CellsSet(cx, cCur+gScolor, rgb)
	} else {
		port.CellsSet(cx, cCur+gFcs, key)
		port.CellsSet(cx, cCur+gFam, cls)
		port.CellsSet(cx, cCur+gColor, rgb)
	}
	return 0
}

func pcDeviceRgb(ox *port.Cells, gx *port.Cells, n int32, space int32) int32 {
	// The colour of the first operands under DeviceGray (space 1), DeviceRGB (2) or DeviceCMYK (3): -1 when there are
	// too few. The conversion is the colour module's, so a colour is the same however it was set.
	var need int32 = 1
	var i int32 = 0
	var v int64 = int64(0)
	if space == 2 {
		need = 3
	}
	if space == 3 {
		need = 4
	}
	if n < need {
		return -1
	}
	for i < need {
		v = pcNum(ox, n, i)
		pdfgfx.GxInput(gx, i, v)
		i += 1
	}
	return pdfgfx.GxEntryRgb(gx, space-1, need)
}

func pcColorDevice(cx *port.Cells, ox *port.Cells, gx *port.Cells, n int32, stroke int32, space int32) int32 {
	// g rg k G RG K: the device space, its class, and the colour.
	var rgb int32 = pcDeviceRgb(ox, gx, n, space)
	if rgb < 0 {
		return 0
	}
	pcSetInk(cx, stroke, 0-space, space, rgb)
	return 0
}

func pcCsOp(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, out *port.Cells, cx *port.Cells, ox *port.Cells, gx *port.Cells, n int32, stroke int32) int32 {
	// cs, CS: the colour space named by operand 0: a device space, Pattern, or a /ColorSpace resource. The colour
	// becomes the space's initial colour. A space this reader cannot read leaves an unknown colour (-1) and no class.
	if n < 1 {
		return 0
	}
	if pcKind(ox, 0) != kName {
		return 0
	}
	var key int32 = 0
	var raw int32 = 0
	var h int32 = 0
	var e int32 = -1
	if pcEntryNameIs(ox, 0, pdfnames.PnDeviceGray()) == 1 {
		key = -1
	}
	if pcEntryNameIs(ox, 0, pdfnames.PnDeviceRgb()) == 1 {
		key = -2
	}
	if pcEntryNameIs(ox, 0, pdfnames.PnDeviceCmyk()) == 1 {
		key = -3
	}
	if pcEntryNameIs(ox, 0, pdfnames.PnPattern()) == 1 {
		key = -4
	}
	if key == 0 {
		raw = pcResEntry(src, ar, dc, a, b, st, cx, ox, pdfnames.PnColorSpace(), 0)
		if raw != 0 {
			h = pdfdoc.PdResolve(src, ar, dc, a, b, st, raw)
		}
		if pdfsrc.PsMissed(src) {
			port.CellsSet(cx, cAbort, 1)
			return 0
		}
		if h != 0 {
			key = pdfgfx.GxKeyOf(src, ar, dc, a, b, st, h)
		}
	}
	if key != 0 {
		e = pdfgfx.GxLookup(src, ar, dc, a, b, st, out, gx, key)
	}
	if pdfsrc.PsMissed(src) {
		port.CellsSet(cx, cAbort, 1)
		return 0
	}
	if e < 0 {
		pcSetInk(cx, stroke, key, 0, -1)
		return 0
	}
	var cls int32 = pdfgfx.GxClass(gx, e)
	var rgb int32 = pdfgfx.GxInitial(gx, e)
	pcSetInk(cx, stroke, key, cls, rgb)
	return 0
}

func pcScOp(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, out *port.Cells, cx *port.Cells, ox *port.Cells, gx *port.Cells, n int32, stroke int32) int32 {
	// sc, scn, SC, SCN: a colour in the current space. A pattern space takes no components (its colour is
	// unknown); a colour whose component count is not the space's is read by its count, as a device colour.
	var key int32 = 0
	var e int32 = -1
	var nn int32 = 0
	var i int32 = 0
	var ncomp int32 = 0
	var rgb int32 = -1
	var cls int32 = 0
	var v int64 = int64(0)
	if stroke == 1 {
		key = port.CellsAt(cx, cCur+gScs)
	} else {
		key = port.CellsAt(cx, cCur+gFcs)
	}
	if key != 0 {
		e = pdfgfx.GxLookup(src, ar, dc, a, b, st, out, gx, key)
	}
	if pdfsrc.PsMissed(src) {
		port.CellsSet(cx, cAbort, 1)
		return 0
	}
	for (nn < n) && (pcKind(ox, nn) == kNum) {
		nn += 1
	}
	if e == -1 {
		// A space that is not known: whatever colour was set is not.
		pcSetInk(cx, stroke, key, 0, -1)
		return 0
	}
	if pdfgfx.GxIsPattern(gx, e) == 1 {
		pcSetInk(cx, stroke, key, 5, -1)
		return 0
	}
	ncomp = pdfgfx.GxNcomp(gx, e)
	if nn > 32 {
		nn = 32
	}
	if (nn > 0) && (nn == ncomp) {
		i = 0
		for i < nn {
			v = pcNum(ox, n, i)
			pdfgfx.GxInput(gx, i, v)
			i += 1
		}
		rgb = pdfgfx.GxEntryRgb(gx, e, nn)
		cls = pdfgfx.GxClass(gx, e)
		pcSetInk(cx, stroke, key, cls, rgb)
		return 0
	}
	// The operands do not fit the space: read them by count, as a device colour, and keep the space.
	if (nn > 0) && ((nn == 1) || ((nn == 3) || (nn == 4))) {
		if nn == 1 {
			rgb = pcDeviceRgb(ox, gx, n, 1)
		}
		if nn == 3 {
			rgb = pcDeviceRgb(ox, gx, n, 2)
		}
		if nn == 4 {
			rgb = pcDeviceRgb(ox, gx, n, 3)
		}
		if stroke == 1 {
			port.CellsSet(cx, cCur+gScolor, rgb)
		} else {
			port.CellsSet(cx, cCur+gColor, rgb)
		}
	}
	return 0
}

func pcBmCode(ar *port.Cells, h int32) int32 {
	// A blend mode name's code: 0 Normal and Compatible, 1 Multiply, 2 Screen, 3 Overlay, 4 Darken, 5 Lighten,
	// 6 ColorDodge, 7 ColorBurn, 8 HardLight, 9 SoftLight, 10 Difference, 11 Exclusion, 12 Hue, 13 Saturation,
	// 14 Color, 15 Luminosity, 99 a name that is none of those.
	if h == 0 {
		return 0
	}
	if pdflex.PlKindOf(ar, h) != 4 {
		return 0
	}
	if (pdfx.PxIs(ar, h, pdfxnames.PxNormal()) == 1) || (pdfx.PxIs(ar, h, pdfxnames.PxCompatible()) == 1) {
		return 0
	}
	if pdfx.PxIs(ar, h, pdfxnames.PxMultiply()) == 1 {
		return 1
	}
	if pdfx.PxIs(ar, h, pdfxnames.PxScreen()) == 1 {
		return 2
	}
	if pdfx.PxIs(ar, h, pdfxnames.PxOverlay()) == 1 {
		return 3
	}
	if pdfx.PxIs(ar, h, pdfxnames.PxDarken()) == 1 {
		return 4
	}
	if pdfx.PxIs(ar, h, pdfxnames.PxLighten()) == 1 {
		return 5
	}
	if pdfx.PxIs(ar, h, pdfxnames.PxColorDodge()) == 1 {
		return 6
	}
	if pdfx.PxIs(ar, h, pdfxnames.PxColorBurn()) == 1 {
		return 7
	}
	if pdfx.PxIs(ar, h, pdfxnames.PxHardLight()) == 1 {
		return 8
	}
	if pdfx.PxIs(ar, h, pdfxnames.PxSoftLight()) == 1 {
		return 9
	}
	if pdfx.PxIs(ar, h, pdfxnames.PxDifference()) == 1 {
		return 10
	}
	if pdfx.PxIs(ar, h, pdfxnames.PxExclusion()) == 1 {
		return 11
	}
	if pdfx.PxIs(ar, h, pdfxnames.PxHue()) == 1 {
		return 12
	}
	if pdfx.PxIs(ar, h, pdfxnames.PxSaturation()) == 1 {
		return 13
	}
	if pdfx.PxIs(ar, h, pdfxnames.PxColor()) == 1 {
		return 14
	}
	if pdfx.PxIs(ar, h, pdfxnames.PxLuminosity()) == 1 {
		return 15
	}
	return 99
}

func pcAlphaOf(ar *port.Cells, h int32) int32 {
	// A constant alpha as per-mille, clamped to 0..1000.
	var al int32 = fx.FxRound(fx.FxMul(pcArFx64(ar, h), fx.FxOfInt(1000)))
	if al < 0 {
		return 0
	}
	if al > 1000 {
		return 1000
	}
	return al
}

func pcGsOp(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, n int32) int32 {
	// gs: the entries of the named ExtGState that matter here: /ca and /CA (alpha), /BM (the blend mode, the first
	// name of an array), /SMask (/None, or a dictionary: its /S, Alpha or Luminosity) and /LW (the line width).
	if n < 1 {
		return 0
	}
	if pcKind(ox, 0) != kName {
		return 0
	}
	var raw int32 = pcResEntry(src, ar, dc, a, b, st, cx, ox, pdfnames.PnExtGState(), 0)
	var gd int32 = 0
	var v int32 = 0
	var s int32 = 0
	if raw == 0 {
		return 0
	}
	gd = pdfdoc.PdResolve(src, ar, dc, a, b, st, raw)
	if pdfsrc.PsMissed(src) {
		port.CellsSet(cx, cAbort, 1)
		return 0
	}
	if gd == 0 {
		return 0
	}
	v = pdfdoc.PdDget(src, ar, dc, a, b, st, gd, pdfnames.PnCa())
	if v != 0 {
		port.CellsSet(cx, cCur+gAlpha, pcAlphaOf(ar, v))
	}
	v = pdfx.PxDget(src, ar, dc, a, b, st, gd, pdfxnames.PxCa())
	if v != 0 {
		port.CellsSet(cx, cCur+gSalpha, pcAlphaOf(ar, v))
	}
	v = pdfx.PxDget(src, ar, dc, a, b, st, gd, pdfxnames.PxBm())
	if v != 0 {
		if pdflex.PlKindOf(ar, v) == 6 {
			s = pdflex.PlFirst(ar, v)
			v = pdfdoc.PdResolve(src, ar, dc, a, b, st, s)
		}
		port.CellsSet(cx, cCur+gBm, pcBmCode(ar, v))
	}
	v = pdfx.PxDget(src, ar, dc, a, b, st, gd, pdfxnames.PxSMask())
	if v != 0 {
		if pdflex.PlKindOf(ar, v) == 4 {
			port.CellsSet(cx, cCur+gSmask, 0)
		}
		if pdflex.PlKindOf(ar, v) == 7 {
			s = pdfx.PxDget(src, ar, dc, a, b, st, v, pdfxnames.PxS())
			port.CellsSet(cx, cCur+gSmask, 2)
			if pdfx.PxIs(ar, s, pdfxnames.PxAlpha()) == 1 {
				port.CellsSet(cx, cCur+gSmask, 1)
			}
		}
	}
	v = pdfx.PxDget(src, ar, dc, a, b, st, gd, pdfxnames.PxLw())
	if v != 0 {
		if pdfx.PxIsNum(ar, v) == 1 {
			fx.FxPut(cx, cCur+gLw, pcArFx64(ar, v))
		}
	}
	if pdfsrc.PsMissed(src) {
		port.CellsSet(cx, cAbort, 1)
	}
	return 0
}

func pcImagePlace(cx *port.Cells, im *port.Cells, obj int32, pxw int32, pxh int32, flags int32) int32 {
	// One image placement (SPEC 8.4.3): the unit square through the CTM. Its box is that parallelogram's, its `rot` the
	// angle of the image's x axis, `skewed` 1 when its axes are not at a right angle (to half a degree).
	var one int64 = fx.FxOne()
	var zero int64 = int64(0)
	var ma int64 = fx.FxGet(cx, cCur+gCtm)
	var mb int64 = fx.FxGet(cx, (cCur+gCtm)+2)
	var mc int64 = fx.FxGet(cx, (cCur+gCtm)+4)
	var md int64 = fx.FxGet(cx, (cCur+gCtm)+6)
	var ax int64 = pcTx(cx, zero, zero)
	var ay int64 = pcTy(cx, zero, zero)
	var bx int64 = pcTx(cx, one, zero)
	var by int64 = pcTy(cx, one, zero)
	var dx int64 = pcTx(cx, one, one)
	var dy int64 = pcTy(cx, one, one)
	var ex int64 = pcTx(cx, zero, one)
	var ey int64 = pcTy(cx, zero, one)
	var rot int32 = pcDirAngle(ma, mb)
	var roty int32 = pcDirAngle(mc, md)
	var diff int32 = 0
	var skew int32 = 1
	var fl int32 = flags
	var chk int32 = 0
	var ori int32 = 0
	var r int32 = 0
	if port.CellsAt(cx, cCur+gBm) != 0 {
		fl += evidence.MgBlend()
	}
	if port.CellsAt(cx, cCur+gSmask) != 0 {
		fl += evidence.MgSoftmask()
	}
	if port.CellsAt(cx, cCur+gBm) != 0 {
		chk += evidence.VcBlend()
	}
	if port.CellsAt(cx, cCur+gSmask) != 0 {
		chk += evidence.VcSoftmask()
	}
	diff = roty - rot
	if diff < 0 {
		diff += 36000
	}
	if (diff >= 8950) && (diff <= 9050) {
		skew = 0
	}
	if (diff >= 26950) && (diff <= 27050) {
		skew = 0
	}
	if port.CellsAt(cx, cNimg) >= pathRows {
		pcWarnSet(cx, wPaths)
		return 0
	}
	r = evidence.ImNew(im, port.CellsAt(cx, cPage), fx.FxRound(pcMin4(ax, bx, dx, ex)), fx.FxRound(pcMin4(ay, by, dy, ey)), fx.FxRound(pcMax4(ax, bx, dx, ex)), fx.FxRound(pcMax4(ay, by, dy, ey)), obj, pxw, pxh)
	evidence.ImSet(im, r, evidence.MfAlpha(), port.CellsAt(cx, cCur+gAlpha))
	evidence.ImSet(im, r, evidence.MfFlags(), fl)
	evidence.ImSet(im, r, evidence.MfRot(), rot)
	evidence.ImSet(im, r, evidence.MfSkewed(), skew)
	// The CTM here maps to the displayed page, whose y runs down: `pi-orient` reads a y-up matrix, so the y axis is flipped
	// back (b and d change sign). 0 is upright on the page AS DISPLAYED (a page's /Rotate is in it), 8 not rectilinear.
	ori = pdfimage.PiOrient(ma, mb*int64(-1), mc, md*int64(-1))
	if ori < 0 {
		ori = 8
	}
	evidence.ImSet(im, r, evidence.MfPlacement(), ori)
	evidence.ImSet(im, r, evidence.MfZ(), port.CellsAt(cx, cZ))
	port.CellsSet(cx, cZ, port.CellsAt(cx, cZ)+1)
	evidence.ImSet(im, r, evidence.MfClip(), port.CellsAt(cx, cCur+gClip))
	evidence.ImSet(im, r, evidence.MfMark(), port.CellsAt(cx, cMctop))
	evidence.ImSet(im, r, evidence.MfOcg(), port.CellsAt(cx, cCurocg))
	evidence.ImSet(im, r, evidence.MfVchk(), chk)
	port.CellsSet(cx, cNimg, port.CellsAt(cx, cNimg)+1)
	return 0
}

func pcOcOpen(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, gx *port.Cells, gl *port.Cells, et *port.Cells, mk *port.Cells, raw int32) int32 {
	// Open an optional-content span for the /OC entry `raw` of a Form XObject or an image (a `marks` row, kind
	// optional-content, flagged `xobject`): its state is `gx-oc-state`'s. Answers 1 when opened, 0 when spans are
	// too deep. The caller closes it with `pc-mc-pop`.
	var depth int32 = port.CellsAt(cx, cMcdepth)
	var span int32 = 0
	var state int32 = 1
	if depth >= maxMc {
		return 0
	}
	state = pdfgfx.GxOcState(src, ar, dc, a, b, st, gx, raw, 0)
	span = evidence.MkOpen(mk, port.CellsAt(cx, cPage), evidence.MkOptionalContent(), port.CellsLen(et), 0, port.CellsAt(cx, cMctop), evidence.GlCount(gl), port.CellsAt(cx, cZ))
	evidence.MkSet(mk, span, evidence.MkfStm(), port.CellsAt(cx, cStm))
	evidence.MkSet(mk, span, evidence.MkfFlags(), evidence.McXobject())
	evidence.MkSet(mk, span, evidence.MkfOcgdef(), state)
	if pdflex.PlKindOf(ar, raw) == 9 {
		evidence.MkSet(mk, span, evidence.MkfOcg(), pdflex.PlIntValue(ar, raw))
	}
	port.CellsSet(cx, cMctop, span)
	port.CellsSet(cx, cMcdepth, depth+1)
	port.CellsSet(cx, cCurocg, span)
	return 1
}

func pcImageDo(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, gx *port.Cells, gl *port.Cells, et *port.Cells, mk *port.Cells, im *port.Cells, objnum int32, xh int32) int32 {
	// Do of an image XObject: a placement row. Its width and height are the dictionary's; the mask flags say what
	// could make it translucent (a stencil mask, an /SMask, a /Mask); an /OC makes it a span of its own.
	var w int32 = pdfdoc.PdDint(src, ar, dc, a, b, st, xh, pdfnames.PnWidth(), 0)
	var h int32 = pdfdoc.PdDint(src, ar, dc, a, b, st, xh, pdfnames.PnHeight(), 0)
	var fl int32 = 0
	var v int32 = 0
	var ocraw int32 = 0
	var opened int32 = 0
	v = pdfx.PxDget(src, ar, dc, a, b, st, xh, pdfxnames.PxImageMask())
	if v != 0 {
		if (pdflex.PlKindOf(ar, v) == 1) && (pdflex.PlIntValue(ar, v) == 1) {
			fl += evidence.MgMask()
		}
	}
	v = pdfx.PxDget(src, ar, dc, a, b, st, xh, pdfxnames.PxSMask())
	if v != 0 {
		fl += evidence.MgSmask()
	}
	v = pdfx.PxDget(src, ar, dc, a, b, st, xh, pdfxnames.PxMask())
	if v != 0 {
		fl += evidence.MgMasked()
	}
	ocraw = pdfx.PxGet(ar, xh, pdfxnames.PxOc())
	if pdfsrc.PsMissed(src) {
		port.CellsSet(cx, cAbort, 1)
		return 0
	}
	if ocraw != 0 {
		opened = pcOcOpen(src, ar, dc, a, b, st, cx, gx, gl, et, mk, ocraw)
	}
	pcImagePlace(cx, im, objnum, w, h, fl)
	if opened == 1 {
		pcMcPop(cx, mk, gl, 0)
	}
	return 0
}

func pcNamePx(ox *port.Cells, s int32, l int32, id int32) int32 {
	// 1 when the name operand bytes ox[s, s+l) are row `id` of the catalogue name table (emon.pdfxnames).
	var n int32 = pdfxnames.PxSpan[id*2+1]
	var o int32 = pdfxnames.PxSpan[id*2+0]
	var i int32 = 0
	if l != n {
		return 0
	}
	for i < n {
		if port.CellsAt(ox, s+i) != pdfxnames.PxChars[o+i] {
			return 0
		}
		i += 1
	}
	return 1
}

func pcFindId(cx *port.Cells, cs *port.Cells) int32 {
	// BI: where the `ID` that ends the inline image's dictionary starts (the index of its `I`), or -1.
	var end int32 = port.CellsAt(cx, cEnd)
	var p int32 = port.CellsAt(cx, cPos)
	for (p + 2) < end {
		if (pcWs(port.CellsAt(cs, p)) == 1) && ((port.CellsAt(cs, p+1) == 73) && ((port.CellsAt(cs, p+2) == 68) && (((p + 3) >= end) || (pcWs(port.CellsAt(cs, p+3)) == 1)))) {
			return p + 1
		}
		p += 1
	}
	return -1
}

func pcInlineImage(cx *port.Cells, ox *port.Cells, cs *port.Cells, im *port.Cells) int32 {
	// BI: read the dictionary up to `ID` (width, height, whether it is a stencil mask), record the placement, then
	// leave the lexer where it was for `pc-skip-inline` to find the end of the data.
	var start int32 = port.CellsAt(cx, cPos)
	var end int32 = port.CellsAt(cx, cEnd)
	var idp int32 = pcFindId(cx, cs)
	var w int32 = 0
	var h int32 = 0
	var fl int32 = 0
	var j int32 = 0
	var v int32 = 0
	var ks int32 = 0
	var kl int32 = 0
	var r int32 = 1
	var total int32 = 0
	var nxt int32 = 0
	if idp < 0 {
		pcImagePlace(cx, im, 0, 0, 0, evidence.MgInline())
		return 0
	}
	port.CellsSet(cx, cEnd, idp)
	pcOxClear(cx, ox)
	for r == 1 {
		r = pcLex(cx, ox, cs)
		if r == 2 {
			r = 0
		}
	}
	total = port.CellsAt(cx, cOxn)
	j = 0
	for j < total {
		nxt = j + 1
		if (pcKind(ox, j) == kName) && (nxt < total) {
			ks = pcEa(ox, j)
			kl = pcEb(ox, j)
			if pcKind(ox, nxt) == kNum {
				v = fx.FxRound(fx.FxJoin(pcEa(ox, nxt), pcEb(ox, nxt)))
				if (pcNameEq(ox, ks, kl, pdfnames.PnWidth()) == 1) || (pcNameEq(ox, ks, kl, pdfnames.PnW()) == 1) {
					w = v
				}
				if (pcNameEq(ox, ks, kl, pdfnames.PnHeight()) == 1) || (pcNamePx(ox, ks, kl, pdfxnames.PxH()) == 1) {
					h = v
				}
			}
			if pcKind(ox, nxt) == kBool {
				if (pcNamePx(ox, ks, kl, pdfxnames.PxIm()) == 1) || (pcNamePx(ox, ks, kl, pdfxnames.PxImageMask()) == 1) {
					if pcEa(ox, nxt) == 1 {
						fl = evidence.MgMask()
					}
				}
			}
			j = nxt + pcEsize(ox, nxt)
		} else {
			j += pcEsize(ox, j)
		}
	}
	port.CellsSet(cx, cEnd, end)
	port.CellsSet(cx, cPos, start)
	pcOxClear(cx, ox)
	pcImagePlace(cx, im, 0, w, h, evidence.MgInline()+fl)
	return 0
}

func pcShOp(cx *port.Cells, pa *port.Cells) int32 {
	// sh: a shading fills the whole clip region. A row of kind `other`, flagged `shading`, whose box is the region's
	// (the page when nothing clips) and whose colour is unknown: P3.6 reads it as paint that is not exactly known.
	var cur int32 = port.CellsAt(cx, cCur+gClip)
	var r int32 = 0
	var bx0 int32 = 0
	var by0 int32 = 0
	var bx1 int32 = 0
	var by1 int32 = 0
	var fl int32 = 0
	if port.CellsAt(cx, cNpath) >= pathRows {
		pcWarnSet(cx, wPaths)
		return 0
	}
	bx0 = 0
	by0 = 0
	bx1 = port.CellsAt(cx, cPw)
	by1 = port.CellsAt(cx, cPh)
	if cur >= 0 {
		bx0 = evidence.PaGet(pa, cur, evidence.PfX0())
		by0 = evidence.PaGet(pa, cur, evidence.PfY0())
		bx1 = evidence.PaGet(pa, cur, evidence.PfX1())
		by1 = evidence.PaGet(pa, cur, evidence.PfY1())
	}
	r = evidence.PaNew(pa, port.CellsAt(cx, cPage), evidence.PaOther(), bx0, by0, bx1, by1)
	fl = evidence.PgFilled() + evidence.PgShading()
	if port.CellsAt(cx, cCur+gBm) != 0 {
		fl += evidence.PgBlend()
	}
	if port.CellsAt(cx, cCur+gSmask) != 0 {
		fl += evidence.PgSoftmask()
	}
	evidence.PaSet(pa, r, evidence.PfFlags(), fl)
	evidence.PaSet(pa, r, evidence.PfFalpha(), port.CellsAt(cx, cCur+gAlpha))
	evidence.PaSet(pa, r, evidence.PfZ(), port.CellsAt(cx, cZ))
	port.CellsSet(cx, cZ, port.CellsAt(cx, cZ)+1)
	evidence.PaSet(pa, r, evidence.PfClip(), cur)
	evidence.PaSet(pa, r, evidence.PfMark(), port.CellsAt(cx, cMctop))
	evidence.PaSet(pa, r, evidence.PfOcg(), port.CellsAt(cx, cCurocg))
	port.CellsSet(cx, cNpath, port.CellsAt(cx, cNpath)+1)
	return 0
}

func pcAppendStream(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, out *port.Cells, cs *port.Cells, sh int32) int32 {
	// Decode stream sh and append its bytes (and a line feed) to `cs`. Answers
	// the filter chain's status (0 ok), or -1 when the source missed.
	var status int32 = pdfdoc.PdStreamData(src, ar, dc, a, b, st, sh, out)
	var n int32 = port.CellsLen(out)
	var i int32 = 0
	if pdfsrc.PsMissed(src) {
		port.CellsSet(cx, cAbort, 1)
		return -1
	}
	if status != 0 {
		pcWarnSet(cx, wStream)
		port.CellsSet(cx, cSstat, status)
	}
	for i < n {
		port.CellsPush(cs, port.CellsAt(out, i))
		i += 1
	}
	port.CellsPush(cs, 10)
	return status
}

func pcDo(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, cs *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, gl *port.Cells, et *port.Cells, mk *port.Cells, fnt *port.Cells, pa *port.Cells, im *port.Cells, pts *port.Cells, gx *port.Cells, n int32) int32 {
	// Do: an image XObject is a placement (`pc-image-do`); a Form XObject is run. The form's /Matrix is
	// concatenated to the CTM, its /BBox clips (a rectangle in its own space), its /Resources replace the current
	// ones (else they are inherited), an /OC makes it an optional-content span, and it runs inside its own `q`/`Q`.
	if n < 1 {
		return 0
	}
	if pcKind(ox, 0) != kName {
		return 0
	}
	var raw int32 = pcResEntry(src, ar, dc, a, b, st, cx, ox, pdfnames.PnXObject(), 0)
	var objnum int32 = 0
	var xh int32 = 0
	var sub int32 = 0
	var fd int32 = 0
	var i int32 = 0
	var mat int32 = 0
	var el int32 = 0
	var got int32 = 0
	var res int32 = 0
	var oldres int32 = 0
	var oldstm int32 = 0
	var start int32 = 0
	var endcs int32 = 0
	var status int32 = 0
	var bb int32 = 0
	var ocraw int32 = 0
	var opened int32 = 0
	var bx0 int64 = int64(0)
	var by0 int64 = int64(0)
	var bx1 int64 = int64(0)
	var by1 int64 = int64(0)
	if pdfsrc.PsMissed(src) {
		port.CellsSet(cx, cAbort, 1)
		return 0
	}
	if raw == 0 {
		pcWarnSet(cx, wForm)
		return 0
	}
	if pdflex.PlKindOf(ar, raw) == 9 {
		objnum = pdflex.PlIntValue(ar, raw)
	}
	xh = pdfdoc.PdResolve(src, ar, dc, a, b, st, raw)
	if pdfsrc.PsMissed(src) {
		port.CellsSet(cx, cAbort, 1)
		return 0
	}
	if xh == 0 {
		pcWarnSet(cx, wForm)
		return 0
	}
	if pdflex.PlKindOf(ar, xh) != 8 {
		return 0
	}
	sub = pdfdoc.PdDget(src, ar, dc, a, b, st, xh, pdfnames.PnSubtype())
	if pdfsrc.PsMissed(src) {
		port.CellsSet(cx, cAbort, 1)
		return 0
	}
	if sub == 0 {
		return 0
	}
	if pdflex.PlNameIs(ar, sub, pdfnames.PnImage()) == 1 {
		pcImageDo(src, ar, dc, a, b, st, cx, gx, gl, et, mk, im, objnum, xh)
		return 0
	}
	if pdflex.PlNameIs(ar, sub, pdfnames.PnForm()) == 0 {
		return 0
	}
	// Depth and cycles: a form deeper than FORM_DEPTH, or already running, is skipped.
	fd = port.CellsAt(cx, cFdepth)
	if (fd >= maxForms) || (fd >= port.CellsAt(cx, cFlim)) {
		pcWarnSet(cx, wDepth)
		return 0
	}
	if objnum != 0 {
		for i < fd {
			if port.CellsAt(cx, cFstack+i) == objnum {
				pcWarnSet(cx, wDepth)
				return 0
			}
			i += 1
		}
	}
	// Its /Matrix (six numbers, else the identity).
	fx.MxIdent(cx, cTmp)
	mat = pdfdoc.PdDget(src, ar, dc, a, b, st, xh, pdfnames.PnMatrix())
	if (mat != 0) && (pdflex.PlKindOf(ar, mat) == 6) {
		el = pdflex.PlFirst(ar, mat)
		got = 0
		for (el != 0) && (got < 6) {
			fx.FxPut(cx, cTmp+(got*2), pcArFx64(ar, el))
			el = pdflex.PlNext(ar, el)
			got += 1
		}
		if got < 6 {
			fx.MxIdent(cx, cTmp)
		}
	}
	// Its /BBox, kept as four Fx until the form's state is made.
	bb = pdfdoc.PdDget(src, ar, dc, a, b, st, xh, pdfnames.PnBBox())
	got = 0
	if (bb != 0) && (pdflex.PlKindOf(ar, bb) == 6) {
		el = pdflex.PlFirst(ar, bb)
		for (el != 0) && (got < 4) {
			sub = pdfdoc.PdResolve(src, ar, dc, a, b, st, el)
			if pdfx.PxIsNum(ar, sub) == 0 {
				got = 0
				el = 0
			} else {
				fx.FxPut(cx, cBb+(got*2), pcArFx64(ar, sub))
				el = pdflex.PlNext(ar, el)
				got += 1
			}
		}
	}
	ocraw = pdfx.PxGet(ar, xh, pdfxnames.PxOc())
	res = pdfdoc.PdDget(src, ar, dc, a, b, st, xh, pdfnames.PnResources())
	oldres = port.CellsAt(cx, cRes)
	oldstm = port.CellsAt(cx, cStm)
	if (res != 0) && (pdflex.PlKindOf(ar, res) == 7) {
		port.CellsSet(cx, cRes, res)
	}
	start = port.CellsLen(cs)
	status = pcAppendStream(src, ar, dc, a, b, st, cx, out, cs, xh)
	if status == -1 {
		return 0
	}
	pcSave(cx)
	fx.MxMul(cx, cCur+gCtm, cTmp, cCur+gCtm)
	if got == 4 {
		// The form's box clips what it paints: a rectangle through the CTM.
		pcPathReset(cx, pts)
		bx0 = fx.FxGet(cx, cBb)
		by0 = fx.FxGet(cx, cBb+2)
		bx1 = fx.FxGet(cx, cBb+4)
		by1 = fx.FxGet(cx, cBb+6)
		pcRectPath(cx, pts, bx0, by0, bx1-bx0, by1-by0)
		port.CellsSet(cx, cClipp, 1)
		pcEndPath(cx, pa, pts, 0, 0, 0, 1)
	}
	if ocraw != 0 {
		opened = pcOcOpen(src, ar, dc, a, b, st, cx, gx, gl, et, mk, ocraw)
	}
	port.CellsSet(cx, cFstack+fd, objnum)
	port.CellsSet(cx, cFdepth, fd+1)
	port.CellsSet(cx, cStm, objnum)
	endcs = port.CellsLen(cs)
	pcRun(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pa, im, pts, gx, start, endcs)
	if opened == 1 {
		pcMcPop(cx, mk, gl, 0)
	}
	port.CellsSet(cx, cFdepth, fd)
	port.CellsSet(cx, cStm, oldstm)
	port.CellsSet(cx, cRes, oldres)
	pcRestore(cx)
	port.CellsDrop(cs, start)
	return 0
}

func pcPrep(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, fnt *port.Cells, et *port.Cells) int32 {
	// Before a string is shown: the font resident, and M = Tm x CTM current.
	pcEnsureFont(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3, fnt, et)
	pcUpdateM(cx)
	if port.CellsAt(cx, cSlot) < 0 {
		pcWarnSet(cx, wText)
	}
	return 0
}

func pcOp(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, cs *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, gl *port.Cells, et *port.Cells, mk *port.Cells, fnt *port.Cells, pa *port.Cells, im *port.Cells, pts *port.Cells, gx *port.Cells, op int32, n int32) int32 {
	// Execute one operator; `ox` holds its n operands. Unknown operators do
	// nothing (their operands are dropped by the caller).
	if op == opSave {
		pcSave(cx)
		return 0
	}
	if op == opRestore {
		pcRestore(cx)
		return 0
	}
	if op == opCm {
		if n >= 6 {
			fx.MxSet(cx, cTmp, pcNum(ox, n, 0), pcNum(ox, n, 1), pcNum(ox, n, 2), pcNum(ox, n, 3), pcNum(ox, n, 4), pcNum(ox, n, 5))
			fx.MxMul(cx, cCur+gCtm, cTmp, cCur+gCtm)
		}
		return 0
	}
	if op == opBt {
		fx.MxIdent(cx, cTm)
		fx.MxIdent(cx, cTlm)
		port.CellsSet(cx, cIntext, 1)
		port.CellsSet(cx, cTcn, 0)
		return 0
	}
	if op == opEt {
		port.CellsSet(cx, cIntext, 0)
		if port.CellsAt(cx, cTcn) > 0 {
			// Glyphs shown in a clipping render mode (4 to 7) clip to their boxes' union (a superset of the glyphs).
			pcClipBox(cx, pa, port.CellsAt(cx, cTcx0), port.CellsAt(cx, cTcy0), port.CellsAt(cx, cTcx1), port.CellsAt(cx, cTcy1), evidence.PaOther(), 0, -1, 0)
			port.CellsSet(cx, cTcn, 0)
		}
		return 0
	}
	if op == opTf {
		pcTf(src, ar, dc, a, b, st, cx, ox, n)
		return 0
	}
	if op == opTchar {
		fx.FxPut(cx, cCur+gTc, pcNum(ox, n, 0))
		return 0
	}
	if op == opTword {
		fx.FxPut(cx, cCur+gTw, pcNum(ox, n, 0))
		return 0
	}
	if op == opTscale {
		fx.FxPut(cx, cCur+gTh, fx.FxMuldiv(pcNum(ox, n, 0), int64(1), int64(100)))
		return 0
	}
	if op == opTlead {
		fx.FxPut(cx, cCur+gTl, pcNum(ox, n, 0))
		return 0
	}
	if op == opTrise {
		fx.FxPut(cx, cCur+gRise, pcNum(ox, n, 0))
		return 0
	}
	if op == opTmode {
		port.CellsSet(cx, cCur+gMode, fx.FxRound(pcNum(ox, n, 0)))
		return 0
	}
	if op == opTd {
		pcTd(cx, pcNum(ox, n, 0), pcNum(ox, n, 1))
		return 0
	}
	if op == opTdl {
		fx.FxPut(cx, cCur+gTl, int64(0)-pcNum(ox, n, 1))
		pcTd(cx, pcNum(ox, n, 0), pcNum(ox, n, 1))
		return 0
	}
	if op == opTm {
		if n >= 6 {
			pcSetTm(cx, pcNum(ox, n, 0), pcNum(ox, n, 1), pcNum(ox, n, 2), pcNum(ox, n, 3), pcNum(ox, n, 4), pcNum(ox, n, 5))
		}
		return 0
	}
	if op == opTstar {
		pcNextLine(cx)
		return 0
	}
	if op == opShow {
		if (n >= 1) && (pcKind(ox, 0) == kStr) {
			pcPrep(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3, fnt, et)
			pcShowStr(cx, ox, gl, et, f0, f1, f2, f3, 0)
		}
		return 0
	}
	if op == opShowarr {
		if (n >= 1) && (pcKind(ox, 0) == kArr) {
			pcPrep(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3, fnt, et)
			pcShowArr(cx, ox, gl, et, f0, f1, f2, f3, 0)
		}
		return 0
	}
	if op == opQuote {
		if (n >= 1) && (pcKind(ox, 0) == kStr) {
			pcNextLine(cx)
			pcPrep(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3, fnt, et)
			pcShowStr(cx, ox, gl, et, f0, f1, f2, f3, 0)
		}
		return 0
	}
	if op == opDquote {
		if (n >= 3) && (pcKind(ox, 2) == kStr) {
			fx.FxPut(cx, cCur+gTw, pcNum(ox, n, 0))
			fx.FxPut(cx, cCur+gTc, pcNum(ox, n, 1))
			pcNextLine(cx)
			pcPrep(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3, fnt, et)
			pcShowStr(cx, ox, gl, et, f0, f1, f2, f3, 2)
		}
		return 0
	}
	if op == opDo {
		pcDo(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pa, im, pts, gx, n)
		return 0
	}
	if op == opBdc {
		pcMcBegin(src, ar, dc, a, b, st, cx, ox, gl, et, mk, fnt, gx, n, 1)
		return 0
	}
	if op == opBmc {
		pcMcBegin(src, ar, dc, a, b, st, cx, ox, gl, et, mk, fnt, gx, n, 0)
		return 0
	}
	if op == opEmc {
		pcMcEnd(cx, mk, gl)
		return 0
	}
	if op == opBi {
		pcInlineImage(cx, ox, cs, im)
		pcSkipInline(cx, cs)
		return 0
	}
	// Colour: the device operators, the named spaces, the components.
	if op == opGray {
		pcColorDevice(cx, ox, gx, n, 0, 1)
		return 0
	}
	if op == opRgb {
		pcColorDevice(cx, ox, gx, n, 0, 2)
		return 0
	}
	if op == opCmyk {
		pcColorDevice(cx, ox, gx, n, 0, 3)
		return 0
	}
	if op == opGrayS {
		pcColorDevice(cx, ox, gx, n, 1, 1)
		return 0
	}
	if op == opRgbS {
		pcColorDevice(cx, ox, gx, n, 1, 2)
		return 0
	}
	if op == opCmykS {
		pcColorDevice(cx, ox, gx, n, 1, 3)
		return 0
	}
	if (op == opSc) || (op == opScn) {
		pcScOp(src, ar, dc, a, b, st, out, cx, ox, gx, n, 0)
		return 0
	}
	if (op == opScS) || (op == opScnS) {
		pcScOp(src, ar, dc, a, b, st, out, cx, ox, gx, n, 1)
		return 0
	}
	if op == opCs {
		pcCsOp(src, ar, dc, a, b, st, out, cx, ox, gx, n, 0)
		return 0
	}
	if op == opCsS {
		pcCsOp(src, ar, dc, a, b, st, out, cx, ox, gx, n, 1)
		return 0
	}
	if op == opGs {
		pcGsOp(src, ar, dc, a, b, st, cx, ox, n)
		return 0
	}
	// Paths: construction, painting, clipping.
	if op == opMove {
		pcOpMove(cx, pts, ox, n)
		return 0
	}
	if op == opLine {
		pcOpLine(cx, pts, ox, n)
		return 0
	}
	if op == opCurve {
		pcOpCurve(cx, pts, ox, n, 0)
		return 0
	}
	if op == opCurveV {
		pcOpCurve(cx, pts, ox, n, 1)
		return 0
	}
	if op == opCurveY {
		pcOpCurve(cx, pts, ox, n, 2)
		return 0
	}
	if op == opClose {
		pcOpClose(cx, pts)
		return 0
	}
	if op == opRect {
		pcOpRect(cx, pts, ox, n)
		return 0
	}
	if (op == opStroke) || ((op == opClosestroke) || ((op == opFill) || ((op == opFill2) || ((op == opFilleo) || ((op == opFs) || ((op == opFseo) || ((op == opCfs) || (op == opCfseo)))))))) {
		pcPaintOp(cx, pa, pts, op)
		return 0
	}
	if op == opEndpath {
		pcEndPath(cx, pa, pts, 0, 0, 0, 0)
		return 0
	}
	if op == opClip {
		port.CellsSet(cx, cClipp, 1)
		return 0
	}
	if op == opClipeo {
		port.CellsSet(cx, cClipp, 2)
		return 0
	}
	if op == opSh {
		pcShOp(cx, pa)
		return 0
	}
	if op == opLw {
		fx.FxPut(cx, cCur+gLw, pcNum(ox, n, 0))
		return 0
	}
	if op == opDash {
		pcDashOp(cx, ox, n)
		return 0
	}
	return 0
}

func pcRun(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, cs *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, gl *port.Cells, et *port.Cells, mk *port.Cells, fnt *port.Cells, pa *port.Cells, im *port.Cells, pts *port.Cells, gx *port.Cells, start int32, end int32) int32 {
	// Run the content bytes cs[start, end): read operands, then execute each
	// operator. The caller's lexer position, graphics-state floor and marked-
	// content floor are kept and restored, so a form can run inside an operator.
	var oldpos int32 = port.CellsAt(cx, cPos)
	var oldend int32 = port.CellsAt(cx, cEnd)
	var oldgs int32 = port.CellsAt(cx, cGsbase)
	var oldmcb int32 = port.CellsAt(cx, cMcbase)
	var oldover int32 = port.CellsAt(cx, cMcover)
	var oldtop int32 = port.CellsAt(cx, cMctop)
	var r int32 = 1
	var opc int32 = 0
	var nop int32 = 0
	var ops int32 = 0
	port.CellsSet(cx, cPos, start)
	port.CellsSet(cx, cEnd, end)
	port.CellsSet(cx, cGsbase, port.CellsAt(cx, cDepth))
	port.CellsSet(cx, cMcbase, port.CellsAt(cx, cMcdepth))
	port.CellsSet(cx, cMcover, 0)
	pcOxClear(cx, ox)
	for (r != 0) && (port.CellsAt(cx, cAbort) == 0) {
		r = pcLex(cx, ox, cs)
		if r == 2 {
			ops = port.CellsAt(cx, cOps) + 1
			port.CellsSet(cx, cOps, ops)
			if ops > port.CellsAt(cx, cOplim) {
				port.LimitBreach(5, ops)
			}
			opc = port.CellsAt(cx, cOp)
			nop = port.CellsAt(cx, cOxn)
			pcOp(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pa, im, pts, gx, opc, nop)
			pcOxClear(cx, ox)
		}
	}
	// What the stream left open: spans, graphics states.
	for port.CellsAt(cx, cMcdepth) > port.CellsAt(cx, cMcbase) {
		pcWarnSet(cx, wMc)
		pcMcPop(cx, mk, gl, 1)
	}
	for port.CellsAt(cx, cDepth) > port.CellsAt(cx, cGsbase) {
		port.CellsSet(cx, cDepth, port.CellsAt(cx, cDepth)-1)
	}
	port.CellsSet(cx, cMctop, oldtop)
	port.CellsSet(cx, cCurocg, evidence.MkOcgOf(mk, oldtop))
	port.CellsSet(cx, cMcover, oldover)
	port.CellsSet(cx, cMcbase, oldmcb)
	port.CellsSet(cx, cGsbase, oldgs)
	port.CellsSet(cx, cPos, oldpos)
	port.CellsSet(cx, cEnd, oldend)
	return 0
}

const wordGapPm int32 = 160

const wordBackPm int32 = 400

const offsetPm int32 = 450

const lineBackPm int32 = 600

const lineGapPm int32 = 2000

func pcAxis(rot int32) int32 {
	// The writing axis a rotation is within three degrees of, else -1 (a glyph run
	// at another angle is measured along its own direction, `pc-rot-gap`).
	var a int32 = ((rot + 4500) / 9000) % 4
	var d int32 = rot - (a * 9000)
	if d < 0 {
		d = 0 - d
	}
	if d > 18000 {
		d = 36000 - d
	}
	if d <= 300 {
		return a
	}
	return -1
}

func pcOffset(gl *port.Cells, j int32, axis int32) int32 {
	// Where glyph j's baseline is across its writing axis, in centipoints.
	if axis == 1 {
		return evidence.GlGet(gl, j, evidence.ChX1())
	}
	if axis == 3 {
		return evidence.GlGet(gl, j, evidence.ChX0())
	}
	return evidence.GlGet(gl, j, evidence.GfBy0())
}

func pcAbs(v int32) int32 {
	if v < 0 {
		return 0 - v
	}
	return v
}

func pcSheared(gl *port.Cells, j int32, axis int32) int32 {
	// D578: 1 when glyph j's box is longer along the writing axis than its baseline segment: the text matrix has a shear term
	// (a synthetic italic: `12 0 4.1041 12 x y Tm`), which leans the cell and makes its axis-aligned box overhang by the shear
	// times the cell's height, on both sides. 0 for the axes a box measures right (and for the others).
	// A glyph with no baseline segment of length (a zero-width mark, or evidence made by hand) is never sheared.
	var bx int32 = pcAbs(evidence.GlGet(gl, j, evidence.GfBx1()) - evidence.GlGet(gl, j, evidence.GfBx0()))
	var by int32 = pcAbs(evidence.GlGet(gl, j, evidence.GfBy1()) - evidence.GlGet(gl, j, evidence.GfBy0()))
	if (axis == 0) || (axis == 2) {
		if (bx > 0) && (((evidence.GlGet(gl, j, evidence.ChX1()) - evidence.GlGet(gl, j, evidence.ChX0())) - bx) > 1) {
			return 1
		}
	}
	if (axis == 1) || (axis == 3) {
		if (by > 0) && (((evidence.GlGet(gl, j, evidence.ChY1()) - evidence.GlGet(gl, j, evidence.ChY0())) - by) > 1) {
			return 1
		}
	}
	return 0
}

func pcGap(gl *port.Cells, p int32, g int32, axis int32) int32 {
	// The space along the axis between glyph p and the glyph g after it
	// (negative when they overlap or g is before p). Between leaning glyphs (a shear term in the text matrix) it is the space
	// between the end of p's baseline segment and the origin of g's, which their boxes only measure when they are upright.
	if (pcSheared(gl, p, axis) == 1) || (pcSheared(gl, g, axis) == 1) {
		if axis == 0 {
			return evidence.GlGet(gl, g, evidence.GfBx0()) - evidence.GlGet(gl, p, evidence.GfBx1())
		}
		if axis == 2 {
			return evidence.GlGet(gl, p, evidence.GfBx1()) - evidence.GlGet(gl, g, evidence.GfBx0())
		}
		if axis == 1 {
			return evidence.GlGet(gl, p, evidence.GfBy1()) - evidence.GlGet(gl, g, evidence.GfBy0())
		}
		return evidence.GlGet(gl, g, evidence.GfBy0()) - evidence.GlGet(gl, p, evidence.GfBy1())
	}
	if axis == 0 {
		return evidence.GlGet(gl, g, evidence.ChX0()) - evidence.GlGet(gl, p, evidence.ChX1())
	}
	if axis == 2 {
		return evidence.GlGet(gl, p, evidence.ChX0()) - evidence.GlGet(gl, g, evidence.ChX1())
	}
	if axis == 1 {
		return evidence.GlGet(gl, p, evidence.ChY0()) - evidence.GlGet(gl, g, evidence.ChY1())
	}
	return evidence.GlGet(gl, g, evidence.ChY0()) - evidence.GlGet(gl, p, evidence.ChY1())
}

func pcRotGap(gl *port.Cells, p int32, g int32, size int32) int32 {
	// For text at an arbitrary angle: the distance between glyph p's centre and
	// glyph g's, along the writing direction, less 60 percent of the size (the
	// two half-advances of adjacent letters), so it reads as `pc-gap` does.
	var rot int32 = evidence.GlGet(gl, p, evidence.GfRot())
	var ux int64 = fx.FxCos(rot)
	var uy int64 = int64(0) - fx.FxSin(rot)
	var dx2 int32 = (evidence.GlGet(gl, g, evidence.ChX0()) + evidence.GlGet(gl, g, evidence.ChX1())) - (evidence.GlGet(gl, p, evidence.ChX0()) + evidence.GlGet(gl, p, evidence.ChX1()))
	var dy2 int32 = (evidence.GlGet(gl, g, evidence.ChY0()) + evidence.GlGet(gl, g, evidence.ChY1())) - (evidence.GlGet(gl, p, evidence.ChY0()) + evidence.GlGet(gl, p, evidence.ChY1()))
	var al2 int64 = fx.FxMul(fx.FxOfInt(dx2), ux) + fx.FxMul(fx.FxOfInt(dy2), uy)
	return fx.FxRound(al2/int64(2)) - ((size * 600) / 1000)
}

func pcRotOff(gl *port.Cells, p int32, g int32) int32 {
	// The distance between the two glyphs' centres across the writing direction.
	var rot int32 = evidence.GlGet(gl, p, evidence.GfRot())
	var sn int64 = fx.FxSin(rot)
	var cs int64 = fx.FxCos(rot)
	var dx2 int32 = (evidence.GlGet(gl, g, evidence.ChX0()) + evidence.GlGet(gl, g, evidence.ChX1())) - (evidence.GlGet(gl, p, evidence.ChX0()) + evidence.GlGet(gl, p, evidence.ChX1()))
	var dy2 int32 = (evidence.GlGet(gl, g, evidence.ChY0()) + evidence.GlGet(gl, g, evidence.ChY1())) - (evidence.GlGet(gl, p, evidence.ChY0()) + evidence.GlGet(gl, p, evidence.ChY1()))
	var pe int32 = fx.FxRound((fx.FxMul(fx.FxOfInt(dx2), sn) + fx.FxMul(fx.FxOfInt(dy2), cs)) / int64(2))
	if pe < 0 {
		return 0 - pe
	}
	return pe
}

func pcPairGap(gl *port.Cells, p int32, g int32, axis int32, size int32) int32 {
	if axis < 0 {
		return pcRotGap(gl, p, g, size)
	}
	return pcGap(gl, p, g, axis)
}

func pcPairOff(gl *port.Cells, p int32, g int32, axis int32) int32 {
	// How far glyph g's baseline is from glyph p's, across the writing axis.
	if axis < 0 {
		return pcRotOff(gl, p, g)
	}
	var d int32 = pcOffset(gl, p, axis) - pcOffset(gl, g, axis)
	if d < 0 {
		return 0 - d
	}
	return d
}

func pcSpaceCp(cp int32) int32 {
	// 1 for a code point that separates words: the spaces (U+0020, U+00A0,
	// U+1680, U+2000..200A, U+202F, U+205F, U+3000) and the tab.
	if (cp == 32) || ((cp == 160) || ((cp == 9) || ((cp == 5760) || ((cp == 8239) || ((cp == 8287) || (cp == 12288)))))) {
		return 1
	}
	if (cp >= 8192) && (cp <= 8202) {
		return 1
	}
	return 0
}

func pcCl(v int32) int32 {
	// Clamp a distance to +-1,000,000 centipoints so a per-mille product fits an I32.
	if v > 1000000 {
		return 1000000
	}
	if v < -1000000 {
		return -1000000
	}
	return v
}

func pcRotSame(r1 int32, r2 int32) int32 {
	// 1 when two rotations (centi-degrees) agree to half a degree.
	var d int32 = r1 - r2
	if d < 0 {
		d = 0 - d
	}
	if d > 18000 {
		d = 36000 - d
	}
	if d <= 50 {
		return 1
	}
	return 0
}

func pcHiddenMode(mode int32) int32 {
	// 1 for the invisible render modes, 3 and 7.
	if (mode == 3) || (mode == 7) {
		return 1
	}
	return 0
}

func pcAccent(cp int32) int32 {
	// D580: the combining mark a spacing diacritic stands for when it is drawn over a letter (TeX draws an umlaut as the glyph
	// dieresis, then the u under it): the dieresis, acute, grave, macron, cedilla, circumflex, caron, breve, dot above, ring,
	// ogonek, small tilde and double acute. 0 for anything else.
	if cp == 168 {
		return 776
	}
	if cp == 180 {
		return 769
	}
	if cp == 96 {
		return 768
	}
	if cp == 175 {
		return 772
	}
	if cp == 184 {
		return 807
	}
	if cp == 710 {
		return 770
	}
	if cp == 711 {
		return 780
	}
	if cp == 728 {
		return 774
	}
	if cp == 729 {
		return 775
	}
	if cp == 730 {
		return 778
	}
	if cp == 731 {
		return 808
	}
	if cp == 732 {
		return 771
	}
	if cp == 733 {
		return 779
	}
	return 0
}

func pcAccentOver(gl *port.Cells, p int32, g int32) int32 {
	// D580: the combining mark that glyph p is when it is a spacing diacritic standing over glyph g, a letter drawn right
	// after it: both upright and of one rotation, no text of their own beyond the one code point, and the middle of the diacritic
	// within the letter's width (Muller is M, the dieresis, then uller backed up under it). 0 when it is not.
	var comb int32 = pcAccent(evidence.GlGet(gl, p, evidence.ChCp()))
	var cx2 int32 = evidence.GlGet(gl, p, evidence.ChX0()) + evidence.GlGet(gl, p, evidence.ChX1())
	if comb == 0 {
		return 0
	}
	if evidence.GlGet(gl, p, evidence.ChTstart()) >= 0 {
		return 0
	}
	if evidence.GlGet(gl, g, evidence.ChTstart()) >= 0 {
		return 0
	}
	if bidi.BdStrong(evidence.GlGet(gl, g, evidence.ChCp())) != 2 {
		return 0
	}
	if pcAxis(evidence.GlGet(gl, p, evidence.GfRot())) != 0 {
		return 0
	}
	if pcRotSame(evidence.GlGet(gl, p, evidence.GfRot()), evidence.GlGet(gl, g, evidence.GfRot())) == 0 {
		return 0
	}
	if evidence.GlGet(gl, p, evidence.GfVis()) != evidence.GlGet(gl, g, evidence.GfVis()) {
		return 0
	}
	if cx2 < (2 * evidence.GlGet(gl, g, evidence.ChX0())) {
		return 0
	}
	if cx2 > (2 * evidence.GlGet(gl, g, evidence.ChX1())) {
		return 0
	}
	return comb
}

func pcAccentPair(gl *port.Cells, j int32, glst int32) int32 {
	// The combining mark glyph j is when it is a spacing diacritic over glyph j+1, which is in the same word (j+1 <= glst); else 0.
	if j >= glst {
		return 0
	}
	return pcAccentOver(gl, j, j+1)
}

func pcContinues(gl *port.Cells, p int32, g int32, first int32) int32 {
	// 1 when glyph g continues the word glyph p is in: the same rotation, on the
	// same baseline (to 45 percent of the size: sub- and superscripts stay), and
	// the gap along the axis neither a word space nor a step back.
	var rot int32 = evidence.GlGet(gl, p, evidence.GfRot())
	var axis int32 = pcAxis(rot)
	var size int32 = evidence.GlGet(gl, g, evidence.GfSize())
	var sizep int32 = evidence.GlGet(gl, p, evidence.GfSize())
	var sz int32 = size
	var gap int32 = 0
	var off int32 = 0
	var basep int32 = p
	if pcRotSame(rot, evidence.GlGet(gl, g, evidence.GfRot())) == 0 {
		return 0
	}
	// A word is one thing to see: a glyph of another visibility, or one that is hidden (mode 3, 7) where the other
	// is not, starts a new word (P3.6).
	if evidence.GlGet(gl, p, evidence.GfVis()) != evidence.GlGet(gl, g, evidence.GfVis()) {
		return 0
	}
	if pcHiddenMode(evidence.GlGet(gl, p, evidence.GfMode())) != pcHiddenMode(evidence.GlGet(gl, g, evidence.GfMode())) {
		return 0
	}
	// A spacing diacritic over the letter drawn right after it is part of that letter's word (D580).
	if pcAccentOver(gl, p, g) > 0 {
		return 1
	}
	// D1833: a nonspacing mark has a displaced baseline and often zero advance. It attaches to the overlapping base; the following letter measures its gap from that base, rather than from the mark.
	if axis == 0 {
		for (basep > first) && (bidi.BdClass(evidence.GlGet(gl, basep, evidence.ChCp())) == 10) && ((p - basep) < 16) {
			basep -= 1
		}
		if (evidence.GlGet(gl, basep, evidence.GfVis()) != evidence.GlGet(gl, p, evidence.GfVis())) || (pcRotSame(evidence.GlGet(gl, basep, evidence.GfRot()), rot) == 0) {
			basep = p
		}
		if bidi.BdClass(evidence.GlGet(gl, g, evidence.ChCp())) == 10 {
			if ((evidence.GlGet(gl, g, evidence.ChX0()) + evidence.GlGet(gl, g, evidence.ChX1())) >= (2 * evidence.GlGet(gl, basep, evidence.ChX0()))) && ((evidence.GlGet(gl, g, evidence.ChX0()) + evidence.GlGet(gl, g, evidence.ChX1())) <= (2 * evidence.GlGet(gl, basep, evidence.ChX1()))) && (pcPairOff(gl, basep, g, axis) <= sz) {
				return 1
			}
		}
	}
	if sizep > sz {
		sz = sizep
	}
	if sz > 200000 {
		sz = 200000
	}
	if sz < (0 - 200000) {
		sz = 0 - 200000
	}
	off = pcCl(pcPairOff(gl, basep, g, axis))
	if (off * 1000) > (sz * offsetPm) {
		return 0
	}
	gap = pcCl(pcPairGap(gl, basep, g, axis, sz))
	if (gap * 1000) > (sz * wordGapPm) {
		return 0
	}
	if (gap * 1000) < (0 - (sz * wordBackPm)) {
		return 0
	}
	return 1
}

func pcGcls(gl *port.Cells, j int32) int32 {
	// 1 when glyph j stands for a strong right-to-left LETTER (Hebrew, Arabic, Syriac, ...: the Unicode class R or
	// AL), 2 for a strong left-to-right letter, else 0. Letters decide the direction of a word and of a line (D162);
	// a digit, a separator or a mark does not.
	return bidi.BdStrong(evidence.GlGet(gl, j, evidence.ChCp()))
}

func pcGlyphOut(et *port.Cells, gl *port.Cells, j int32, lvl int32) int32 {
	// Append glyph j's text (every code point it stands for, or U+FFFD) to the evidence text. At bidi level 1
	// (lvl, L4) a text of ONE code point whose character is mirrored (a bracket) is the mirror: the glyph on the
	// page was drawn as the mirror image of the character it stands for.
	var ts int32 = evidence.GlGet(gl, j, evidence.ChTstart())
	var tl int32 = evidence.GlGet(gl, j, evidence.ChTlen())
	var cp int32 = evidence.GlGet(gl, j, evidence.ChCp())
	var k int32 = 0
	var cpv int32 = 0
	if (ts >= 0) && (tl > 0) {
		for k < tl {
			cpv = port.CellsAt(et, ts+k)
			if (lvl == 1) && (tl == 1) {
				cpv = bidi.BdMirror(cpv)
			}
			evidence.EtxAppendCp(et, cpv)
			k += 1
		}
		return 0
	}
	if cp >= 0 {
		if lvl == 1 {
			cp = bidi.BdMirror(cp)
		}
		evidence.EtxAppendCp(et, cp)
	} else {
		evidence.EtxAppendCp(et, 65533)
	}
	return 0
}

func pcBidiText(et *port.Cells, gl *port.Cells, gfst int32, glst int32) int32 {
	// Append the text of glyphs [gfst, glst], which were SHOWN left to right, in LOGICAL order of a right-to-left
	// paragraph (`emon.bidi`, D162): the order the Bidirectional Algorithm would display them in. It is written
	// where the arena ended, moved down over the scratch the algorithm used, and the index it starts at is the
	// answer. (The scratch is the arena's own tail: the algorithm owns no memory.)
	var n int32 = (glst - gfst) + 1
	var b int32 = port.CellsLen(et)
	var j int32 = 0
	var o int32 = 0
	var e int32 = 0
	var i int32 = 0
	var lv int32 = 0
	var k int32 = 0
	for j < n {
		port.CellsPush(et, evidence.GlGet(gl, gfst+j, evidence.ChCp()))
		j += 1
	}
	o = bidi.BdOrderOf(et, b, n)
	e = port.CellsLen(et)
	j = 0
	for j < n {
		i = port.CellsAt(et, o+j)
		lv = port.CellsAt(et, (o-n)+i)
		pcGlyphOut(et, gl, gfst+i, lv)
		j += 1
	}
	k = 0
	for k < (port.CellsLen(et) - e) {
		port.CellsSet(et, b+k, port.CellsAt(et, e+k))
		k += 1
	}
	port.CellsDrop(et, b+(port.CellsLen(et)-e))
	return b
}

func PcBaseGlyph(gl *port.Cells, gfst int32, glst int32, fromEnd int32) int32 {
	// P12.7 (smoke A N2): the glyph a word's baseline is read from at its start (from-end 0) or at its end (1): the first (last) of its glyphs that is not set small against the biggest of the
	// word (at most 80 per cent of its size). The raised digits of a footnote marker, `white¹,`, sit above the line's baseline: a word's baseline is not theirs, or the rows of a table that
	// sorts its words by baseline put `bread¹,` before `White`. The last (first) glyph itself when none is, or the word has one glyph.
	var mx int32 = 0
	var j int32 = gfst
	for j <= glst {
		if evidence.GlGet(gl, j, evidence.GfSize()) > mx {
			mx = evidence.GlGet(gl, j, evidence.GfSize())
		}
		j += 1
	}
	// Compare against floor(4 * mx / 5), dividing first so huge glyph sizes cannot overflow (identity fuzz corpus).
	if fromEnd == 1 {
		j = glst
		for j >= gfst {
			if evidence.GlGet(gl, j, evidence.GfSize()) > (((mx / 5) * 4) + (((mx % 5) * 4) / 5)) {
				return j
			}
			j -= 1
		}
	} else {
		j = gfst
		for j <= glst {
			if evidence.GlGet(gl, j, evidence.GfSize()) > (((mx / 5) * 4) + (((mx % 5) * 4) / 5)) {
				return j
			}
			j += 1
		}
	}
	if fromEnd == 1 {
		return glst
	}
	return gfst
}

func pcEmitWord(gl *port.Cells, et *port.Cells, wd *port.Cells, fnt *port.Cells, page int32, gfst int32, glst int32, wbk int32) int32 {
	// Record glyphs [gfst, glst] as a word: the union of their boxes, their text, the
	// dominant font and size of the first, and `hidden-text` as its source when every
	// glyph is render mode 3. A right-to-left word whose glyphs run left to right on the
	// page (visual order, as Skia and most producers write them) has its TEXT written in
	// logical order by the Bidirectional Algorithm (`pc-bidi-text`, D162): numbers and their separators,
	// Latin runs, brackets and the neutrals between them as UAX #9 resolves them, not letter by letter. A word
	// with no letter to say so ("2026,") is put right once its line is known to be right to left
	// (`pc-word-fix`). The glyphs themselves stay as they were shown.
	var x0 int32 = evidence.GlGet(gl, gfst, evidence.ChX0())
	var y0 int32 = evidence.GlGet(gl, gfst, evidence.ChY0())
	var x1 int32 = evidence.GlGet(gl, gfst, evidence.ChX1())
	var y1 int32 = evidence.GlGet(gl, gfst, evidence.ChY1())
	var j int32 = gfst
	var tstart int32 = -1
	var visible int32 = 0
	var nr int32 = 0
	var nl int32 = 0
	var cl int32 = 0
	var rtlw int32 = 0
	for j <= glst {
		if evidence.GlGet(gl, j, evidence.ChX0()) < x0 {
			x0 = evidence.GlGet(gl, j, evidence.ChX0())
		}
		if evidence.GlGet(gl, j, evidence.ChY0()) < y0 {
			y0 = evidence.GlGet(gl, j, evidence.ChY0())
		}
		if evidence.GlGet(gl, j, evidence.ChX1()) > x1 {
			x1 = evidence.GlGet(gl, j, evidence.ChX1())
		}
		if evidence.GlGet(gl, j, evidence.ChY1()) > y1 {
			y1 = evidence.GlGet(gl, j, evidence.ChY1())
		}
		if (evidence.GlGet(gl, j, evidence.GfMode()) != 3) && (evidence.GlGet(gl, j, evidence.GfMode()) != 7) {
			visible = 1
		}
		cl = pcGcls(gl, j)
		if cl == 1 {
			nr += 1
		}
		if cl == 2 {
			nl += 1
		}
		j += 1
	}
	if (nr > nl) && (glst > gfst) {
		if pcAxis(evidence.GlGet(gl, gfst, evidence.GfRot())) == 0 {
			if evidence.GlGet(gl, glst, evidence.ChX0()) >= evidence.GlGet(gl, gfst, evidence.ChX0()) {
				rtlw = 1
			}
		}
	}
	tstart = port.CellsLen(et)
	if rtlw == 0 {
		j = gfst
		for j <= glst {
			// a spacing diacritic over the next letter of the word is written AFTER the letter, as the combining mark (D580)
			cl = pcAccentPair(gl, j, glst)
			if cl > 0 {
				pcGlyphOut(et, gl, j+1, 2)
				evidence.EtxAppendCp(et, cl)
				j += 2
			} else {
				pcGlyphOut(et, gl, j, 2)
				j += 1
			}
		}
	} else {
		tstart = pcBidiText(et, gl, gfst, glst)
	}
	var gb0 int32 = PcBaseGlyph(gl, gfst, glst, 0)
	var gb1 int32 = PcBaseGlyph(gl, gfst, glst, 1)
	var w int32 = evidence.WdNew(wd, page, x0, y0, x1, y1, evidence.GlGet(gl, gfst, evidence.GfBx0()), evidence.GlGet(gl, gb0, evidence.GfBy0()), evidence.GlGet(gl, glst, evidence.GfBx1()), evidence.GlGet(gl, gb1, evidence.GfBy1()), evidence.GlGet(gl, gfst, evidence.GfRot()), 0, tstart, port.CellsLen(et)-tstart, -1, -1, -1)
	var fo int32 = evidence.GlGet(gl, gfst, evidence.GfFont())
	if rtlw == 1 {
		evidence.WdSet(wd, w, evidence.HdDir(), evidence.LdRtl())
	}
	evidence.WdSet(wd, w, evidence.WfGfirst(), gfst)
	evidence.WdSet(wd, w, evidence.WfGcount(), (glst-gfst)+1)
	evidence.WdSet(wd, w, evidence.WfFont(), fo)
	evidence.WdSet(wd, w, evidence.WfSize(), evidence.GlGet(gl, gfst, evidence.GfSize()))
	if (fo >= 0) && (fo < evidence.FoCount(fnt)) {
		evidence.WdSet(wd, w, evidence.WfStyle(), evidence.FoGet(fnt, fo, evidence.FnfStyle()))
	}
	evidence.WdSet(wd, w, evidence.WfWbreak(), wbk)
	if visible == 0 {
		evidence.WdSet(wd, w, evidence.WfSrc(), model.SrHiddenText())
	}
	j = gfst
	for j <= glst {
		evidence.GlSet(gl, j, evidence.ChWord(), w)
		j += 1
	}
	return w
}

func pcSwapRows(wd *port.Cells, i int32, j int32) int32 {
	var k int32 = 0
	var u int32 = 0
	var v int32 = 0
	for k < 24 {
		u = port.CellsAt(wd, (i*24)+k)
		v = port.CellsAt(wd, (j*24)+k)
		port.CellsSet(wd, (i*24)+k, v)
		port.CellsSet(wd, (j*24)+k, u)
		k += 1
	}
	return 0
}

func pcRevRows(wd *port.Cells, a int32, b int32) int32 {
	var i int32 = a
	var j int32 = b
	for i < j {
		pcSwapRows(wd, i, j)
		i += 1
		j -= 1
	}
	return 0
}

func pcWcls(gl *port.Cells, wd *port.Cells, w int32) int32 {
	// What a word is to the order of the words of a right-to-left line: 1 when it has a right-to-left letter,
	// 2 when it has a left-to-right letter and no right-to-left one, 3 when it is only numbers (and what goes
	// with them), 0 when it is only neutrals (a dash, a bullet).
	var g0 int32 = evidence.WdGet(wd, w, evidence.WfGfirst())
	var gn int32 = evidence.WdGet(wd, w, evidence.WfGcount())
	var j int32 = 0
	var nr int32 = 0
	var nl int32 = 0
	var nn int32 = 0
	var cl int32 = 0
	for j < gn {
		cl = pcGcls(gl, g0+j)
		if cl == 1 {
			nr += 1
		}
		if cl == 2 {
			nl += 1
		}
		cl = bidi.BdClass(evidence.GlGet(gl, g0+j, evidence.ChCp()))
		if (cl == 3) || (cl == 4) {
			nn += 1
		}
		j += 1
	}
	if nr > 0 {
		return 1
	}
	if nl > 0 {
		return 2
	}
	if nn > 0 {
		return 3
	}
	return 0
}

func pcWordFix(gl *port.Cells, et *port.Cells, wd *port.Cells, w int32) int32 {
	// A word of a right-to-left line that `pc-emit-word` left in the order it was shown, because nothing in it
	// said it was right to left ("2026,", "50%", "(1)", "ROI-" before a Hebrew letter): when its glyphs run
	// left to right on the page they are in visual order, so its text is put in logical order, as a word that
	// says so is. Done in place: the same code points, in the order the algorithm gives; nothing moves if the
	// order does not change. Answers 1 when it changed the text.
	var g0 int32 = evidence.WdGet(wd, w, evidence.WfGfirst())
	var gn int32 = evidence.WdGet(wd, w, evidence.WfGcount())
	var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
	var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
	var b int32 = port.CellsLen(et)
	var j int32 = 0
	var o int32 = 0
	var e int32 = 0
	var i int32 = 0
	var lv int32 = 0
	var changed int32 = 0
	if gn < 2 {
		return 0
	}
	if evidence.WdGet(wd, w, evidence.HdDir()) == evidence.LdRtl() {
		return 0
	}
	if pcAxis(evidence.GlGet(gl, g0, evidence.GfRot())) != 0 {
		return 0
	}
	if evidence.GlGet(gl, g0+(gn-1), evidence.ChX0()) < evidence.GlGet(gl, g0, evidence.ChX0()) {
		return 0
	}
	for j < gn {
		port.CellsPush(et, evidence.GlGet(gl, g0+j, evidence.ChCp()))
		j += 1
	}
	o = bidi.BdOrderOf(et, b, gn)
	j = 0
	for j < gn {
		i = port.CellsAt(et, o+j)
		lv = port.CellsAt(et, (o-gn)+i)
		if (i != j) || (lv == 1) {
			changed = 1
		}
		j += 1
	}
	if changed == 0 {
		port.CellsDrop(et, b)
		return 0
	}
	e = port.CellsLen(et)
	j = 0
	for j < gn {
		i = port.CellsAt(et, o+j)
		lv = port.CellsAt(et, (o-gn)+i)
		pcGlyphOut(et, gl, g0+i, lv)
		j += 1
	}
	if (port.CellsLen(et) - e) != tl {
		port.CellsDrop(et, b)
		return 0
	}
	j = 0
	for j < tl {
		port.CellsSet(et, ts+j, port.CellsAt(et, e+j))
		j += 1
	}
	port.CellsDrop(et, b)
	return 1
}

func pcLineBidi(gl *port.Cells, et *port.Cells, wd *port.Cells, ln *port.Cells, lidx int32, wfst int32, wlst int32) int32 {
	// Line lidx holds words [wfst, wlst]. When more of its letters are right-to-left than left-to-right
	// it is a right-to-left line (`ld-rtl`). Its words that no letter put in logical order are put in it
	// (`pc-word-fix`); if the words run left to right on the page, their ORDER is made logical: reversed,
	// with each group of words that make one left-to-right run (Latin words, and the numbers and neutrals
	// between them, W7 and N1) turned back; each word's glyphs are re-pointed at it and its gap is the
	// space to the word that follows it in that order.
	var w int32 = wfst
	var nr int32 = 0
	var nl int32 = 0
	var j int32 = 0
	var cl int32 = 0
	var a int32 = 0
	var z int32 = 0
	var s int32 = 0
	var hasl int32 = 0
	var rtl int32 = 0
	var g0 int32 = 0
	var gn int32 = 0
	for w <= wlst {
		g0 = evidence.WdGet(wd, w, evidence.WfGfirst())
		gn = evidence.WdGet(wd, w, evidence.WfGcount())
		j = 0
		for j < gn {
			cl = pcGcls(gl, g0+j)
			if cl == 1 {
				nr += 1
			}
			if cl == 2 {
				nl += 1
			}
			j += 1
		}
		w += 1
	}
	// A paragraph's direction is its own, not each line's: a short last line that is mostly Latin (a
	// product name, an acronym) after a right-to-left line is still right to left (UAX #9, P2 and P3 read
	// the paragraph, and the lines of one run on). So a line is right to left when its right-to-left
	// letters outnumber the left-to-right ones, or when the line before it (same page) is and this one has a
	// right-to-left letter or no left-to-right one (a number, a bullet).
	rtl = 0
	if nr > nl {
		rtl = 1
	}
	if (lidx > 0) && (rtl == 0) {
		if evidence.LnGet(ln, lidx-1, evidence.LhPage()) == evidence.LnGet(ln, lidx, evidence.LhPage()) {
			if evidence.LnGet(ln, lidx-1, evidence.LhDir()) == evidence.LdRtl() {
				if (nr > 0) || (nl == 0) {
					rtl = 1
				}
			}
		}
	}
	if rtl == 0 {
		return 0
	}
	evidence.LnSet(ln, lidx, evidence.LhDir(), evidence.LdRtl())
	w = wfst
	for w <= wlst {
		pcWordFix(gl, et, wd, w)
		w += 1
	}
	if pcAxis(evidence.GlGet(gl, evidence.WdGet(wd, wfst, evidence.WfGfirst()), evidence.GfRot())) != 0 {
		return 0
	}
	if evidence.WdGet(wd, wlst, evidence.HdX0()) < evidence.WdGet(wd, wfst, evidence.HdX0()) {
		return 0
	}
	if wfst == wlst {
		return 0
	}
	pcRevRows(wd, wfst, wlst)
	// Now the rows are in logical order but for the left-to-right runs, which are backwards: a run is a
	// maximal stretch of words that are not right-to-left, holding at least one left-to-right word, less
	// the neutral-only words at its ends (they are between a left-to-right and a right-to-left word: N2).
	a = wfst
	for a <= wlst {
		if pcWcls(gl, wd, a) == 1 {
			a += 1
		} else {
			z = a
			for (z < wlst) && (pcWcls(gl, wd, z+1) != 1) {
				z += 1
			}
			hasl = 0
			s = a
			for s <= z {
				if pcWcls(gl, wd, s) == 2 {
					hasl = 1
				}
				s += 1
			}
			if hasl == 1 {
				s = a
				for pcWcls(gl, wd, s) == 0 {
					s += 1
				}
				j = z
				for pcWcls(gl, wd, j) == 0 {
					j -= 1
				}
				pcRevRows(wd, s, j)
			}
			a = z + 1
		}
	}
	w = wfst
	for w <= wlst {
		g0 = evidence.WdGet(wd, w, evidence.WfGfirst())
		gn = evidence.WdGet(wd, w, evidence.WfGcount())
		j = 0
		for j < gn {
			evidence.GlSet(gl, g0+j, evidence.ChWord(), w)
			j += 1
		}
		z = -1
		if w < wlst {
			z = evidence.WdGet(wd, w, evidence.HdX0()) - evidence.WdGet(wd, w+1, evidence.HdX1())
		}
		evidence.WdSet(wd, w, evidence.WfGap(), z)
		w += 1
	}
	return 0
}

const nojoin int32 = 2000000

const mergeMax int32 = 256

func pcSameBase(gl *port.Cells, wd *port.Cells, p int32, j int32) int32 {
	// 1 when word j is on word p's baseline: the same rotation, and the offset across the writing axis, from p's last glyph to j's
	// first, within `OFFSET_PM` of the larger size.
	var gfp int32 = evidence.WdGet(wd, p, evidence.WfGfirst())
	var gf0 int32 = evidence.WdGet(wd, j, evidence.WfGfirst())
	var axis int32 = pcAxis(evidence.GlGet(gl, gfp, evidence.GfRot()))
	var sz int32 = evidence.GlGet(gl, gf0, evidence.GfSize())
	var glast int32 = (gfp + evidence.WdGet(wd, p, evidence.WfGcount())) - 1
	if pcRotSame(evidence.GlGet(gl, gfp, evidence.GfRot()), evidence.GlGet(gl, gf0, evidence.GfRot())) == 0 {
		return 0
	}
	if evidence.GlGet(gl, gfp, evidence.GfSize()) > sz {
		sz = evidence.GlGet(gl, gfp, evidence.GfSize())
	}
	if sz > 200000 {
		sz = 200000
	}
	if sz < (0 - 200000) {
		sz = 0 - 200000
	}
	if (pcCl(pcPairOff(gl, glast, gf0, axis)) * 1000) <= (sz * offsetPm) {
		return 1
	}
	return 0
}

func pcJoinGap(gl *port.Cells, wd *port.Cells, p int32, j int32) int32 {
	// The rule that puts word j on word p's line: the same rotation and baseline (`pc-same-base`), and a gap from p's LAST glyph to j's
	// first that is at most `LINE_GAP_PM` of the larger size and at most `LINE_BACK_PM` back. Answers the gap, or `NOJOIN`.
	var gfp int32 = evidence.WdGet(wd, p, evidence.WfGfirst())
	var gf0 int32 = evidence.WdGet(wd, j, evidence.WfGfirst())
	var axis int32 = pcAxis(evidence.GlGet(gl, gfp, evidence.GfRot()))
	var sz int32 = evidence.GlGet(gl, gf0, evidence.GfSize())
	var gap int32 = 0
	var glast int32 = (gfp + evidence.WdGet(wd, p, evidence.WfGcount())) - 1
	if pcSameBase(gl, wd, p, j) == 0 {
		return nojoin
	}
	if evidence.GlGet(gl, gfp, evidence.GfSize()) > sz {
		sz = evidence.GlGet(gl, gfp, evidence.GfSize())
	}
	if sz > 200000 {
		sz = 200000
	}
	if sz < (0 - 200000) {
		sz = 0 - 200000
	}
	// The gap is between the previous word's LAST glyph and this word's first.
	gap = pcCl(pcPairGap(gl, glast, gf0, axis, sz))
	if (gap * 1000) < (0 - (sz * lineBackPm)) {
		return nojoin
	}
	if (gap * 1000) > (sz * lineGapPm) {
		return nojoin
	}
	return gap
}

func pcMergeSpan(gl *port.Cells, wd *port.Cells, s int32, t int32) int32 {
	// Words [s, t] are runs of the stream on one baseline that are not in order along it. When every one is horizontal, of one visibility
	// and has no right-to-left letter, and each word, taken in order of x, joins the one after it by `pc-join-gap`, they are put in that
	// order (a stable insertion sort of the word rows; the glyphs are pointed at their word again) and are one line to the loop that
	// follows. Otherwise nothing moves. Answers 1 when the words were put in order.
	var g0 int32 = evidence.WdGet(wd, s, evidence.WfGfirst())
	var i int32 = s
	var j int32 = 0
	var k int32 = 0
	var best int32 = 0
	var asc int32 = 1
	var gi int32 = 0
	i = s + 1
	for i <= t {
		if evidence.WdGet(wd, i, evidence.HdX0()) < evidence.WdGet(wd, i-1, evidence.HdX0()) {
			asc = 0
		}
		i += 1
	}
	if asc == 1 {
		return 0
	}
	i = s
	for i <= t {
		gi = evidence.WdGet(wd, i, evidence.WfGfirst())
		if pcAxis(evidence.GlGet(gl, gi, evidence.GfRot())) != 0 {
			return 0
		}
		if evidence.GlGet(gl, gi, evidence.GfVis()) != evidence.GlGet(gl, g0, evidence.GfVis()) {
			return 0
		}
		if pcHiddenMode(evidence.GlGet(gl, gi, evidence.GfMode())) != pcHiddenMode(evidence.GlGet(gl, g0, evidence.GfMode())) {
			return 0
		}
		if evidence.WdGet(wd, i, evidence.HdDir()) == evidence.LdRtl() {
			return 0
		}
		if pcWcls(gl, wd, i) == 1 {
			return 0
		}
		i += 1
	}
	// Each word's successor in order of x (ties by place in the stream): it must continue the word.
	i = s
	for i <= t {
		best = -1
		j = s
		for j <= t {
			if (evidence.WdGet(wd, j, evidence.HdX0()) > evidence.WdGet(wd, i, evidence.HdX0())) || ((evidence.WdGet(wd, j, evidence.HdX0()) == evidence.WdGet(wd, i, evidence.HdX0())) && (j > i)) {
				if best < 0 {
					best = j
				} else if evidence.WdGet(wd, j, evidence.HdX0()) < evidence.WdGet(wd, best, evidence.HdX0()) {
					best = j
				}
			}
			j += 1
		}
		if best >= 0 {
			if pcJoinGap(gl, wd, i, best) >= nojoin {
				return 0
			}
		}
		i += 1
	}
	i = s + 1
	for i <= t {
		j = i
		for (j > s) && (evidence.WdGet(wd, j-1, evidence.HdX0()) > evidence.WdGet(wd, j, evidence.HdX0())) {
			pcSwapRows(wd, j-1, j)
			j -= 1
		}
		i += 1
	}
	i = s
	for i <= t {
		gi = evidence.WdGet(wd, i, evidence.WfGfirst())
		k = 0
		for k < evidence.WdGet(wd, i, evidence.WfGcount()) {
			evidence.GlSet(gl, gi+k, evidence.ChWord(), i)
			k += 1
		}
		if (i < t) && (evidence.WdGet(wd, i, evidence.WfWbreak()) == evidence.WbLineEnd()) {
			evidence.WdSet(wd, i, evidence.WfWbreak(), evidence.WbGap())
		}
		i += 1
	}
	return 1
}

func pcMergeLines(gl *port.Cells, wd *port.Cells, w0 int32) int32 {
	// The words from w0 on, before they are cut into lines: where consecutive runs of the stream (each a stretch of words that
	// `pc-join-gap` joins) are on one baseline, they are one candidate (at most `MERGE_MAX` words) and `pc-merge-span` puts them in
	// order along it if they make one line. A run that is already in order along the baseline is left alone (a wide gap in it ends the line, as
	// ever: a column gutter or a table cell). Answers the spans put in order.
	var nw int32 = evidence.WdCount(wd)
	var s int32 = w0
	var t int32 = 0
	var u int32 = 0
	var nseg int32 = 0
	var more int32 = 0
	var done int32 = 0
	for s < nw {
		t = s
		for ((t + 1) < nw) && (pcJoinGap(gl, wd, t, t+1) < nojoin) {
			t += 1
		}
		nseg = 1
		more = 1
		for (more == 1) && (((t + 1) < nw) && ((t - s) < mergeMax)) {
			if pcSameBase(gl, wd, t, t+1) == 1 {
				u = t + 1
				for ((u + 1) < nw) && (pcJoinGap(gl, wd, u, u+1) < nojoin) {
					u += 1
				}
				t = u
				nseg += 1
			} else {
				more = 0
			}
		}
		if (nseg > 1) && ((t - s) <= mergeMax) {
			done += pcMergeSpan(gl, wd, s, t)
		}
		s = t + 1
	}
	return done
}

func PcGroup(gl *port.Cells, et *port.Cells, wd *port.Cells, ln *port.Cells, fnt *port.Cells, page int32, g0 int32, w0 int32) int32 {
	// Group the glyphs from g0 on into words, and the words from w0 on into lines.
	var g1 int32 = evidence.GlCount(gl)
	var i int32 = g0
	var cur int32 = -1
	for i < g1 {
		if pcSpaceCp(evidence.GlGet(gl, i, evidence.ChCp())) == 1 {
			if cur >= 0 {
				pcEmitWord(gl, et, wd, fnt, page, cur, i-1, evidence.WbSpace())
				cur = -1
			}
		} else {
			if cur >= 0 {
				if pcContinues(gl, i-1, i, cur) == 0 {
					pcEmitWord(gl, et, wd, fnt, page, cur, i-1, evidence.WbGap())
					cur = -1
				}
			}
			if cur < 0 {
				cur = i
			}
		}
		i += 1
	}
	if cur >= 0 {
		pcEmitWord(gl, et, wd, fnt, page, cur, g1-1, evidence.WbLineEnd())
		cur = -1
	}
	// Lines: consecutive words on one baseline, in order.
	var nw int32 = evidence.WdCount(wd)
	var j int32 = w0
	var lfirst int32 = -1
	var prev int32 = -1
	var lnx int32 = 0
	var x0 int32 = 0
	var y0 int32 = 0
	var x1 int32 = 0
	var y1 int32 = 0
	var gfp int32 = 0
	var joins int32 = 0
	var gap int32 = 0
	var ord int32 = 0
	pcMergeLines(gl, wd, w0)
	for j <= nw {
		joins = 0
		if (j < nw) && (prev >= 0) {
			gap = pcJoinGap(gl, wd, prev, j)
			if gap < nojoin {
				joins = 1
			}
		}
		if joins == 1 {
			evidence.WdSet(wd, prev, evidence.WfGap(), gap)
			prev = j
		} else {
			// The line so far ends at `prev`: record it, then start a new one at j.
			if lfirst >= 0 {
				x0 = evidence.WdGet(wd, lfirst, evidence.HdX0())
				y0 = evidence.WdGet(wd, lfirst, evidence.HdY0())
				x1 = evidence.WdGet(wd, lfirst, evidence.HdX1())
				y1 = evidence.WdGet(wd, lfirst, evidence.HdY1())
				lnx = lfirst
				for lnx <= prev {
					if evidence.WdGet(wd, lnx, evidence.HdX0()) < x0 {
						x0 = evidence.WdGet(wd, lnx, evidence.HdX0())
					}
					if evidence.WdGet(wd, lnx, evidence.HdY0()) < y0 {
						y0 = evidence.WdGet(wd, lnx, evidence.HdY0())
					}
					if evidence.WdGet(wd, lnx, evidence.HdX1()) > x1 {
						x1 = evidence.WdGet(wd, lnx, evidence.HdX1())
					}
					if evidence.WdGet(wd, lnx, evidence.HdY1()) > y1 {
						y1 = evidence.WdGet(wd, lnx, evidence.HdY1())
					}
					lnx += 1
				}
				gfp = evidence.WdGet(wd, lfirst, evidence.WfGfirst())
				ord = evidence.WdGet(wd, lfirst, evidence.WfGfirst())
				lnx = lfirst
				for lnx <= prev {
					if evidence.WdGet(wd, lnx, evidence.WfGfirst()) < ord {
						ord = evidence.WdGet(wd, lnx, evidence.WfGfirst())
					}
					lnx += 1
				}
				// The baseline runs from the first word's start to the last word's end, in the
				// order the words were SHOWN (the bidi step below re-orders the rows, not the page).
				lnx = evidence.LnNew(ln, page, x0, y0, x1, y1, evidence.WdGet(wd, lfirst, evidence.HdBx0()), evidence.WdGet(wd, lfirst, evidence.HdBy0()), evidence.WdGet(wd, prev, evidence.HdBx1()), evidence.WdGet(wd, prev, evidence.HdBy1()), evidence.GlGet(gl, gfp, evidence.GfRot()), 0, lfirst, (prev-lfirst)+1)
				evidence.LnSet(ln, lnx, evidence.LfOrder(), ord)
				pcLineBidi(gl, et, wd, ln, lnx, lfirst, prev)
				evidence.WdSet(wd, prev, evidence.WfWbreak(), evidence.WbLineEnd())
				gfp = lfirst
				for gfp <= prev {
					evidence.WdSet(wd, gfp, evidence.HdLine(), lnx)
					gfp += 1
				}
			}
			lfirst = j
			prev = j
		}
		j += 1
	}
	return 0
}

func pcBeginPage(cx *port.Cells, page int32) int32 {
	// Reset everything a page owns; the fonts (the document's) stay.
	port.CellsSet(cx, cPage, page)
	port.CellsSet(cx, cWarn, 0)
	port.CellsSet(cx, cOps, 0)
	port.CellsSet(cx, cAbort, 0)
	port.CellsSet(cx, cPos, 0)
	port.CellsSet(cx, cEnd, 0)
	port.CellsSet(cx, cOxn, 0)
	port.CellsSet(cx, cCdepth, 0)
	port.CellsSet(cx, cOp, 0)
	port.CellsSet(cx, cRes, 0)
	port.CellsSet(cx, cSlot, -1)
	port.CellsSet(cx, cDepth, 0)
	port.CellsSet(cx, cFdepth, 0)
	port.CellsSet(cx, cStm, 0)
	port.CellsSet(cx, cMctop, -1)
	port.CellsSet(cx, cMcdepth, 0)
	port.CellsSet(cx, cMcbase, 0)
	port.CellsSet(cx, cMcover, 0)
	port.CellsSet(cx, cCurocg, -1)
	port.CellsSet(cx, cZ, 0)
	port.CellsSet(cx, cIntext, 0)
	port.CellsSet(cx, cClipp, 0)
	port.CellsSet(cx, cTcn, 0)
	port.CellsSet(cx, cNpath, 0)
	port.CellsSet(cx, cNimg, 0)
	port.CellsSet(cx, cGsbase, 0)
	fx.MxIdent(cx, cTm)
	fx.MxIdent(cx, cTlm)
	fx.MxIdent(cx, cM)
	return 0
}

func PcPage(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, cs *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, gl *port.Cells, et *port.Cells, mk *port.Cells, fnt *port.Cells, pg *port.Cells, pi int32, page int32, wd *port.Cells, ln *port.Cells, pa *port.Cells, im *port.Cells, pts *port.Cells, gx *port.Cells) int32 {
	// Interpret page index pi of the page table pg (page number `page`, 1-based, is
	// what the evidence records): its content streams, then the words and lines.
	// Answers 0, or 7 (`need-bytes`) when the source missed: then nothing written is
	// to be used and the caller re-runs on a fresh view (D075).
	var con int32 = pdfdoc.PdPgContents(pg, pi)
	var g0 int32 = evidence.GlCount(gl)
	var w0 int32 = evidence.WdCount(wd)
	var p0 int32 = evidence.PaCount(pa)
	var i0 int32 = evidence.ImCount(im)
	var rot int32 = pdfdoc.PdPgRotate(pg, pi)
	var cw int32 = pdfdoc.PdPgCrop(pg, pi, 2) - pdfdoc.PdPgCrop(pg, pi, 0)
	var ch int32 = pdfdoc.PdPgCrop(pg, pi, 3) - pdfdoc.PdPgCrop(pg, pi, 1)
	var el int32 = 0
	var eh int32 = 0
	var endcs int32 = 0
	pcBeginPage(cx, page)
	port.CellsSet(cx, cPts0, evidence.PtCount(pts))
	pcBaseMatrix(cx, pdfdoc.PdPgCrop(pg, pi, 0), pdfdoc.PdPgCrop(pg, pi, 1), pdfdoc.PdPgCrop(pg, pi, 2), pdfdoc.PdPgCrop(pg, pi, 3), pdfdoc.PdPgRotate(pg, pi))
	pcGsReset(cx)
	pdfgfx.GxPage(gx)
	pdfgfx.GxOcRead(src, ar, dc, a, b, st, gx)
	if (rot == 90) || (rot == 270) {
		port.CellsSet(cx, cPw, ch)
		port.CellsSet(cx, cPh, cw)
	} else {
		port.CellsSet(cx, cPw, cw)
		port.CellsSet(cx, cPh, ch)
	}
	pcPathReset(cx, pts)
	port.CellsSet(cx, cRes, pdfdoc.PdPgResources(pg, pi))
	port.CellsDrop(cs, 0)
	if con != 0 {
		if pdflex.PlKindOf(ar, con) == 8 {
			pcAppendStream(src, ar, dc, a, b, st, cx, out, cs, con)
		}
		if pdflex.PlKindOf(ar, con) == 6 {
			el = pdflex.PlFirst(ar, con)
			for (el != 0) && (port.CellsAt(cx, cAbort) == 0) {
				eh = pdfdoc.PdResolve(src, ar, dc, a, b, st, el)
				if pdfsrc.PsMissed(src) {
					port.CellsSet(cx, cAbort, 1)
				}
				if (eh != 0) && (pdflex.PlKindOf(ar, eh) == 8) {
					pcAppendStream(src, ar, dc, a, b, st, cx, out, cs, eh)
				}
				el = pdflex.PlNext(ar, el)
			}
		}
	}
	if port.CellsAt(cx, cAbort) == 1 {
		return 7
	}
	endcs = port.CellsLen(cs)
	pcRun(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pa, im, pts, gx, 0, endcs)
	if port.CellsAt(cx, cAbort) == 1 {
		return 7
	}
	if pdfsrc.PsMissed(src) {
		return 7
	}
	// The path in progress when the page ended never painted: its points are dropped.
	port.CellsDrop(pts, port.CellsAt(cx, cPpts)*3)
	pdfvis.PvPage(gl, mk, pa, im, port.CellsAt(cx, cPw), port.CellsAt(cx, cPh), g0, p0, i0)
	PcGroup(gl, et, wd, ln, fnt, page, g0, w0)
	return 0
}

func PcDocument(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, cs *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, gl *port.Cells, et *port.Cells, mk *port.Cells, fnt *port.Cells, pg *port.Cells, wd *port.Cells, ln *port.Cells, pa *port.Cells, im *port.Cells, pts *port.Cells, gx *port.Cells) int32 {
	// Every page of an opened document (`pd-open` has answered 0): clears `cx`,
	// then `pc-page` for each page. Answers 0, or 7 when the source missed.
	PcInit(cx, ox)
	port.CellsDrop(fnt, 0)
	port.CellsDrop(gx, 0)
	var n int32 = pdfdoc.PdPages(src, ar, dc, a, b, st, pg)
	var i int32 = 0
	var status int32 = 0
	if n < 0 {
		return 7
	}
	for i < n {
		status = PcPage(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, i, i+1, wd, ln, pa, im, pts, gx)
		if status == 7 {
			return 7
		}
		i += 1
	}
	return 0
}
